// TableBitWriter uses the packet wire's low-bit-first order. Measuring walks
// the identical stream, including alignment, without touching a buffer.
type TableBitWriter struct {
	Buffer              []byte
	Bits                int64
	Measuring, Overflow bool
}

func (w *TableBitWriter) Put(value uint64, n int64) {
	if n < 0 || n > 64 {
		w.Overflow = true
		return
	}
	if n == 0 {
		return
	}
	at := w.Bits
	w.Bits += n
	if w.Bits < at {
		w.Overflow = true
		return
	}
	if w.Measuring {
		return
	}
	if (w.Bits+7)/8 > int64(len(w.Buffer)) {
		w.Overflow = true
		return
	}
	if n < 64 {
		value &= (uint64(1) << n) - 1
	}
	index := at >> 3
	shift := at & 7
	head := uint64(0)
	if shift != 0 {
		head = uint64(w.Buffer[index]) & ((uint64(1) << shift) - 1)
	}
	word := head | value<<shift
	need := (shift + n + 7) / 8
	if need >= 8 {
		binary.LittleEndian.PutUint64(w.Buffer[index:], word)
		if need > 8 {
			w.Buffer[index+8] = byte(value >> (64 - shift))
		}
	} else {
		for j := int64(0); j < need; j++ {
			w.Buffer[index+j] = byte(word >> (j * 8))
		}
	}
}
func (w *TableBitWriter) Align() { w.Put(0, (-w.Bits)&7) }
func (w *TableBitWriter) Raw(data []byte) {
	w.Align()
	if w.Measuring {
		w.Bits += int64(len(data)) * 8
		return
	}
	at := w.Bits / 8
	w.Bits += int64(len(data)) * 8
	if at > int64(len(w.Buffer))-int64(len(data)) {
		w.Overflow = true
		return
	}
	copy(w.Buffer[at:], data)
}

type TableBitReader struct {
	Buffer []byte
	Offset int64
}

func (r *TableBitReader) Get(n int64) (uint64, bool) {
	if n < 0 || n > 64 || r.Offset < 0 || n > int64(len(r.Buffer))*8-r.Offset {
		return 0, false
	}
	if n == 0 {
		return 0, true
	}
	at := r.Offset >> 3
	shift := r.Offset & 7
	need := (shift + n + 7) / 8
	var value uint64
	if need >= 8 {
		value = binary.LittleEndian.Uint64(r.Buffer[at:]) >> shift
		if need > 8 {
			value |= uint64(r.Buffer[at+8]) << (64 - shift)
		}
	} else {
		for j := int64(0); j < need; j++ {
			value |= uint64(r.Buffer[at+j]) << (8 * j)
		}
		value >>= shift
	}
	if n < 64 {
		value &= (uint64(1) << n) - 1
	}
	r.Offset += n
	return value, true
}
func (r *TableBitReader) Skip(n int64) bool {
	if n < 0 || n > int64(len(r.Buffer))*8-r.Offset {
		return false
	}
	r.Offset += n
	return true
}
func (r *TableBitReader) Align() bool { v, ok := r.Get((-r.Offset) & 7); return ok && v == 0 }
func tableMessageBits(n uint64) int64 {
	var count int64
	for n != 0 {
		count++
		n >>= 1
	}
	return count
}

type TableMessageShape struct {
	Kind, Packing uint8
	Bits          int64
	Base          [2]uint64
	Min, Max      int64
	QMin, QDelta  float32
	QCount        uint32
}
type TableMessageEntry struct {
	Id             uint64
	Shape, Element TableMessageShape
}

// Storage belongs to the caller and is resolved once for one connection direction.
type TableVocabulary struct {
	Entries            []TableMessageEntry
	Count, RefBits     int64
	BuildVersion       uint64
	Announced, Refused bool
	MaxBytes           int64
	Strict             bool
}

func (v *TableVocabulary) Init(storage []TableMessageEntry) {
	*v = TableVocabulary{Entries: storage, MaxBytes: 64 * 1024}
}
func (v *TableVocabulary) Entry(ref uint64) (TableMessageEntry, bool) {
	if ref == 0 || ref > uint64(v.Count) {
		return TableMessageEntry{}, false
	}
	return v.Entries[ref-1], true
}
func (v *TableVocabulary) Name(ref uint64) (uint64, bool) {
	e, ok := v.Entry(ref)
	return e.Id, ok && e.Shape.Kind == 0 && e.Id < 0xfffffffffffffffd
}
func tableMessageNameSlot(id uint64) uint64 {
	for i := range tableMessageEntries {
		e := &tableMessageEntries[i]
		if e.Id == id && e.Shape.Kind == 0 {
			return uint64(i + 1)
		}
	}
	return 0
}
func AnnounceMeasure() int64 { return int64(len(tableAnnouncement)) }
func Announce(buffer []byte) int64 {
	if len(buffer) < len(tableAnnouncement) {
		return -1
	}
	copy(buffer, tableAnnouncement[:])
	return int64(len(tableAnnouncement))
}
func tableMessageRefuse(r *TableReport, reason string) bool {
	r.Verdict = TableOpenRefused
	r.Reason = reason
	return false
}
func AnnounceRead(v *TableVocabulary, data []byte, report *TableReport) bool {
	if report == nil {
		var ignored TableReport
		report = &ignored
	}
	if v.Announced || v.Refused {
		return tableMessageRefuse(report, "second_announcement")
	}
	ok := tableAnnounceRead(v, data, report)
	if !ok {
		v.Refused = true
	}
	return ok
}
func tableAnnounceRead(v *TableVocabulary, data []byte, report *TableReport) bool {
	r, verdict := tableOpenFramed(data, report)
	if verdict != TableOpenOk {
		if verdict == TableOpenRefused {
			reason := "newer_form"
			if len(data) > 0 && data[0] == 2 {
				reason = "message_form_as_file"
			}
			return tableMessageRefuse(report, reason)
		}
		report.Malformed = true
		return false
	}
	versionCount, wordsCount := 0, 0
	var words []byte
	for {
		ref, ok := r.Leb()
		if !ok {
			report.Malformed = true
			return false
		}
		if ref == 0 {
			break
		}
		id, ok := r.Resolve(ref)
		if !ok || !r.Has(1) {
			report.Malformed = true
			return false
		}
		kind := r.Get8()
		switch id {
		case 0xfffffffffffffffe:
			if kind != 9 || !r.Has(8) {
				report.Malformed = true
				return false
			}
			v.BuildVersion = r.Get64()
			versionCount++
		case 0xfffffffffffffffd:
			if kind != 14 {
				report.Malformed = true
				return false
			}
			sub, ok := r.Body()
			if !ok || !sub.Has(1) || sub.Get8() != 6 {
				report.Malformed = true
				return false
			}
			n, ok := sub.Leb()
			if !ok || n > uint64(len(sub.Buffer)) || int64(n) != int64(len(sub.Buffer))-sub.Offset {
				report.Malformed = true
				return false
			}
			limit := v.MaxBytes
			if limit == 0 {
				limit = 64 * 1024
			}
			if int64(n) > limit {
				return tableMessageRefuse(report, "vocabulary_too_large")
			}
			words = sub.Buffer[sub.Offset:]
			wordsCount++
		default:
			report.Unknown++
			if !r.Skip(kind) {
				report.Malformed = true
				return false
			}
		}
	}
	if versionCount != 1 || wordsCount != 1 {
		report.Malformed = true
		return false
	}
	if v.Strict && v.BuildVersion != BuildVersion {
		report.BuildVersionPeer = v.BuildVersion
		report.BuildVersionOwn = BuildVersion
		return tableMessageRefuse(report, "build_version_mismatch")
	}
	src := TableReader{Buffer: words, Report: report}
	count := int64(0)
	nodeSeen := false
	for src.Offset < int64(len(words)) {
		if count >= int64(len(v.Entries)) {
			return tableMessageRefuse(report, "vocabulary_too_large")
		}
		began := src.Offset
		e, ok := tableMessageEntryRead(&src)
		if !ok || e.Id == 0xfffffffffffffffd || e.Id == 0xfffffffffffffffe || e.Id == 0xffffffffffffffff && nodeSeen {
			report.Malformed = true
			return false
		}
		if e.Id == 0xffffffffffffffff {
			nodeSeen = true
		}
		for i := int64(0); i < count; i++ {
			o := v.Entries[i].Shape
			if o.Max-o.Min == src.Offset-began && o.Min >= 0 && o.Max <= int64(len(words)) {
				same := true
				for j := o.Min; j < o.Max; j++ {
					if words[j] != words[began+j-o.Min] {
						same = false
						break
					}
				}
				if same {
					report.Malformed = true
					return false
				}
			}
		}
		e.Shape.Min = began
		e.Shape.Max = src.Offset
		v.Entries[count] = e
		count++
	}
	src.Offset = 0
	for i := int64(0); i < count; i++ {
		e, ok := tableMessageEntryRead(&src)
		if !ok {
			report.Malformed = true
			return false
		}
		v.Entries[i] = e
	}
	v.Count = count
	v.RefBits = tableMessageBits(uint64(count))
	if v.RefBits == 0 {
		v.RefBits = 1
	}
	v.Announced = true
	return true
}

// THE SHAPE IS THE DECLARED ONE, the bytes the announcement spells, and never
// the resolved entry: a resolved quantized entry keeps §4.3's derivation and
// not the max and res it consumed, so two declared shapes that derive one delta
// and count would read as one entry there, and a legitimate announcement, the
// unit's own included, would be refused as malformed (#722). Go's == on float32
// also equates +0 and -0, whose declared bytes differ. The entry's encoding is
// canonical, a minimal LEB128 and fixed four-byte floats, so byte equality is
// declared-fact equality, bit pattern for bit pattern. Each accepted entry parks
// its byte extent in Shape.Min and Shape.Max until the scan is over, and the
// second pass in tableAnnounceRead resolves every entry in place, so no offset
// into the announcement outlives the call. The scan is quadratic in the entry
// count, and the entry count is bounded above at 4096, so it is at most eight
// million compares on a path that runs ONCE a connection and never again. The
// compare is spelled inline so the emitter claims no new runtime name.
func tableMessageKnownKind(k uint8) bool { return k <= 33 }
func tableMessageKindBits(k uint8) int64 {
	if k == 0 || k == 32 {
		return 0
	}
	if k == 1 {
		return 1
	}
	switch k {
	case 2, 6, 20, 25:
		return 8
	case 3, 7, 21, 26:
		return 16
	case 4, 8, 10, 22, 27:
		return 32
	case 5, 9, 11, 23, 28:
		return 64
	case 18, 19, 24, 29:
		return 128
	}
	return -1
}
func tableMessageShapeRead(r *TableReader, k uint8) (s TableMessageShape, ok bool) {
	s.Kind = k
	s.Bits = tableMessageKindBits(k)
	switch {
	case k >= 2 && k <= 10 || k >= 18 && k <= 29:
		if !r.Has(1) {
			return s, false
		}
		s.Packing = r.Get8()
		if s.Packing == 0 {
			return s, true
		}
		if s.Packing == 1 && k != 10 {
			n, ok := r.Leb()
			if !ok || n > uint64(s.Bits) {
				return s, false
			}
			s.Bits = int64(n)
			if k >= 18 {
				if !r.Has(16) {
					return s, false
				}
				s.Base = [2]uint64{r.Get64(), r.Get64()}
			} else {
				base, ok := r.Leb()
				if !ok {
					return s, false
				}
				if k >= 2 && k <= 5 {
					base = uint64(int64(base>>1) ^ -int64(base&1))
				}
				s.Base[0] = base
			}
			return s, true
		}
		if s.Packing == 2 && k == 10 {
			if !r.Has(12) {
				return s, false
			}
			lo := math.Float32frombits(r.Get32())
			hi := math.Float32frombits(r.Get32())
			res := math.Float32frombits(r.Get32())
			if !(lo < hi) || !(res > 0) {
				return s, false
			}
			delta := float32(hi - lo)
			values := float32(delta / res)
			if delta-delta != 0 || values-values != 0 {
				return s, false
			}
			if !(values >= 1) {
				values = 1
			} else if values > 4294967040.0 {
				values = 4294967040.0
			}
			s.QMin = lo
			s.QDelta = delta
			s.QCount = uint32(math.Ceil(float64(values)))
			s.Bits = tableMessageBits(uint64(s.QCount))
			return s, true
		}
		return s, false
	case k == 12 || k == 33:
		n, ok := r.Leb()
		if !ok || n > math.MaxInt32 {
			return s, false
		}
		s.Max = int64(n)
	case k == 14 || k == 16:
		if k == 14 {
			n, ok := r.Leb()
			if !ok || n > math.MaxUint32 {
				return s, false
			}
			s.Min = int64(n)
		}
		n, ok := r.Leb()
		if !ok || n > math.MaxUint32 || int64(n) < s.Min {
			return s, false
		}
		s.Max = int64(n)
	}
	return s, true
}
func tableMessageEntryRead(r *TableReader) (e TableMessageEntry, ok bool) {
	if !r.Has(9) {
		return e, false
	}
	e.Id = r.Get64()
	kind := r.Get8()
	if !tableMessageKnownKind(kind) {
		return e, false
	}
	e.Shape, ok = tableMessageShapeRead(r, kind)
	if !ok {
		return e, false
	}
	if kind == 14 || kind == 16 {
		if !r.Has(1) {
			return e, false
		}
		elem := r.Get8()
		if !tableMessageKnownKind(elem) || elem == 12 || elem == 33 {
			return e, false
		}
		e.Element, ok = tableMessageShapeRead(r, elem)
		if !ok {
			return e, false
		}
		if elem == 14 || elem == 16 {
			if !r.Has(1) {
				return e, false
			}
			inner := r.Get8()
			if !tableMessageKnownKind(inner) || inner == 12 || inner == 33 {
				return e, false
			}
		}
	}
	return e, true
}
func tableMessageCount(r *TableBitReader, s TableMessageShape) (uint64, bool) {
	raw, ok := r.Get(tableMessageBits(uint64(s.Max - s.Min)))
	return raw + uint64(s.Min), ok
}
func tableMessageSkip(r *TableBitReader, v *TableVocabulary, indexBits int64, e TableMessageEntry, depth int) bool {
	if depth > 128 {
		return false
	}
	s := e.Shape
	switch s.Kind {
	case 0, 32:
		return true
	case 30:
		ref, ok := r.Get(v.RefBits)
		if !ok || ref == 0 {
			return ok
		}
		_, ok = v.Name(ref)
		return ok
	case 13:
		return tableMessageSkipBody(r, v, indexBits, depth+1)
	case 17:
		return indexBits > 0 && r.Skip(indexBits)
	case 15:
		ref, ok := r.Get(v.RefBits)
		if !ok || ref == 0 {
			return ok
		}
		arm, ok := v.Entry(ref)
		return ok && arm.Id < 0xfffffffffffffffd && arm.Shape.Kind != 0 && tableMessageSkip(r, v, indexBits, arm, depth+1)
	case 12, 33:
		n, ok := tableMessageCount(r, s)
		if !ok {
			return false
		}
		width := int64(16)
		if s.Kind == 12 {
			width = 8
			if !r.Align() {
				return false
			}
		}
		return r.Skip(int64(n) * width)
	case 31:
		if !r.Align() {
			return false
		}
		n, ok := r.Get(32)
		return ok && r.Skip(int64(n)*8)
	case 14, 16:
		n, ok := tableMessageCount(r, s)
		if !ok {
			return false
		}
		if s.Kind == 14 && e.Element.Kind == 6 && !r.Align() {
			return false
		}
		if e.Element.Bits >= 0 || e.Element.Kind == 0 || e.Element.Kind == 32 {
			width := e.Element.Bits
			if width < 0 {
				width = 0
			}
			if s.Kind == 16 {
				width += v.RefBits
			}
			return r.Skip(int64(n) * width)
		}
		for i := uint64(0); i < n; i++ {
			if s.Kind == 16 && !r.Skip(v.RefBits) {
				return false
			}
			before := r.Offset
			if !tableMessageSkip(r, v, indexBits, TableMessageEntry{Shape: e.Element}, depth+1) || r.Offset == before {
				return false
			}
		}
		return true
	}
	return s.Bits >= 0 && r.Skip(s.Bits)
}

// Framing scans follow announced shapes; typed body reads diagnose reserved ids.
func tableMessageSkipBody(r *TableBitReader, v *TableVocabulary, indexBits int64, depth int) bool {
	if depth > 128 {
		return false
	}
	for {
		ref, ok := r.Get(v.RefBits)
		if !ok || ref == 0 {
			return ok
		}
		e, ok := v.Entry(ref)
		if !ok || !tableMessageSkip(r, v, indexBits, e, depth) {
			return false
		}
	}
}

// Numeric values are reconstructed at the announced storage width. Typed
// readers then apply the existing exact file-domain clamps to these lanes.
func tableMessageReadScalar(r *TableBitReader, s TableMessageShape, out *[16]byte) bool {
	lo, ok := r.Get(min(s.Bits, 64))
	if !ok {
		return false
	}
	hi := uint64(0)
	if s.Bits > 64 {
		hi, ok = r.Get(s.Bits - 64)
		if !ok {
			return false
		}
	}
	if s.Packing == 1 {
		sum := lo + s.Base[0]
		carry := uint64(0)
		if sum < lo {
			carry = 1
		}
		lo = sum
		hi += s.Base[1] + carry
	}
	if s.Packing == 2 {
		index := min(uint32(lo), s.QCount)
		ratio := float32(float32(index) / float32(s.QCount))
		scaled := float32(ratio * s.QDelta)
		lo = uint64(math.Float32bits(float32(scaled + s.QMin)))
	}
	binary.LittleEndian.PutUint64(out[:], lo)
	binary.LittleEndian.PutUint64(out[8:], hi)
	return true
}
func tableMessageWriteScalar(w *TableBitWriter, s TableMessageShape, lo, hi uint64) {
	if s.Packing == 1 {
		borrow := uint64(0)
		if lo < s.Base[0] {
			borrow = 1
		}
		lo -= s.Base[0]
		hi -= s.Base[1] + borrow
	}
	if s.Packing == 2 {
		value := math.Float32frombits(uint32(lo))
		ratio := float32((value - s.QMin) / s.QDelta)
		if !(ratio >= 0) {
			ratio = 0
		} else if !(ratio <= 1) {
			ratio = 1
		}
		scaled := float32(ratio * float32(s.QCount))
		lo = uint64(min(uint32(math.Floor(float64(float32(scaled+0.5)))), s.QCount))
	}
	w.Put(lo, min(s.Bits, 64))
	if s.Bits > 64 {
		w.Put(hi, s.Bits-64)
	}
}

type TableMessageReader struct {
	Nodes      TableNodeMap
	Bits       TableBitReader
	Vocabulary *TableVocabulary
	Report     TableReport
	IndexBits  int64
}

func tableMessageBatchOpen(v *TableVocabulary, data []byte, report *TableReport) (TableMessageReader, int64) {
	r := TableMessageReader{Vocabulary: v, Report: *report}
	defer func() { *report = r.Report }()
	if len(data) == 0 {
		r.Report.Malformed = true
		return r, -1
	}
	if data[0] != 2 {
		tableMessageRefuse(&r.Report, "newer_form")
		return r, -1
	}
	if v == nil || !v.Announced {
		tableMessageRefuse(&r.Report, "no_vocabulary")
		return r, -1
	}
	if len(data) < 2 {
		r.Report.Malformed = true
		return r, -1
	}
	r.Bits.Buffer = data[2:]
	return r, int64(data[1]) + 1
}
func tableMessageBatchClose(r *TableMessageReader) bool {
	if !r.Bits.Align() || r.Bits.Offset != int64(len(r.Bits.Buffer))*8 {
		r.Report.Malformed = true
		return false
	}
	return true
}

type TableMessageWriter struct {
	TableBitWriter
	IndexBits int64
	Numbering *TableNumbering
	numbering TableNumbering
}

func tableMessageRegionWrite(w *TableMessageWriter, p unsafe.Pointer, t *TableTypeInfo, a *TableArena, allocator ...TableAllocator) bool {
	var ok bool
	w.numbering, ok = tableNumber(p, t, a, allocator...)
	if !ok {
		return false
	}
	n := &w.numbering
	defer n.Release()
	defer func() { w.Numbering = nil }()
	w.Numbering = n
	w.IndexBits = tableMessageBits(uint64(len(n.entries)))
	if w.IndexBits < 1 {
		w.IndexBits = 1
	}
	if len(n.entries) > 1 {
		slot := uint64(0)
		for i := range tableMessageEntries {
			if tableMessageEntries[i].Id == 0xffffffffffffffff {
				slot = uint64(i + 1)
				break
			}
		}
		if slot == 0 || uint64(len(n.entries)-1) > math.MaxUint32 {
			return false
		}
		w.Put(slot, TableMessageRefBitsHere)
		w.Put(uint64(len(n.entries)-1), 32)
		for i := 1; i < len(n.entries); i++ {
			node := &n.entries[i]
			slot := tableMessageNameSlot(node.id)
			if slot == 0 {
				return false
			}
			w.Put(slot, TableMessageRefBitsHere)
			if node.info != nil {
				if !node.info.SaveMessageBody(w, node.node) {
					return false
				}
			} else {
				length := uint64(*(*uint32)(node.node))
				if length > math.MaxUint32 {
					return false
				}
				w.Put(length, 32)
				w.Raw(unsafe.Slice((*byte)(unsafe.Add(node.node, 8)), int(length)))
			}
		}
	}
	return t.SaveMessageBody(w, p)
}
func tableMessageNodeOpen(r *TableMessageReader) (int64, bool) {
	start := r.Bits.Offset
	ref, ok := r.Bits.Get(r.Vocabulary.RefBits)
	if !ok {
		return 0, false
	}
	if ref == 0 {
		r.Bits.Offset = start
		return 0, true
	}
	e, ok := r.Vocabulary.Entry(ref)
	if !ok {
		return 0, false
	}
	if e.Id != 0xffffffffffffffff {
		r.Bits.Offset = start
		return 0, true
	}
	n, ok := r.Bits.Get(32)
	return int64(n), ok
}
func tableMessageExtent(r *TableMessageReader, t *TableTypeInfo, at *int64) bool {
	return tableMessageSkipBody(&r.Bits, r.Vocabulary, r.IndexBits, 0)
}

type tableMessageRecord struct {
	id           uint64
	size, length int64
}

func tableMessageRecordScan(r *TableMessageReader, root *TableTypeInfo, blobs int) (record tableMessageRecord, ok bool) {
	ref, ok := r.Bits.Get(r.Vocabulary.RefBits)
	if !ok {
		return record, false
	}
	record.id, ok = r.Vocabulary.Name(ref)
	if !ok {
		return record, false
	}
	if record.id == tableBytesTypeId || record.id == tableStringTypeId {
		n, ok := r.Bits.Get(32)
		if !ok || !r.Bits.Align() || !r.Bits.Skip(int64(n)*8) {
			return record, false
		}
		record.length = int64(n)
		if record.id == tableBytesTypeId && blobs&1 != 0 || record.id == tableStringTypeId && blobs&2 != 0 {
			extra := int64(0)
			if record.id == tableStringTypeId {
				extra = 1
			}
			record.size = tableRegionRound(8 + record.length + extra)
		}
		return record, true
	}
	t := root.NodeType(record.id)
	if t == nil {
		return record, tableMessageSkipBody(&r.Bits, r.Vocabulary, r.IndexBits, 0)
	}
	extent := int64(0)
	if !tableMessageExtent(r, t, &extent) {
		return record, false
	}
	record.size = tableRegionRound(tableRegionRound(int64(t.Size)) + extent)
	return record, true
}
func tableMessageBodyStorage(r *TableMessageReader, root *TableTypeInfo, blobs int) (size int64, complete, ok bool) {
	count, ok := tableMessageNodeOpen(r)
	if !ok {
		return 0, false, false
	}
	r.IndexBits = tableMessageBits(uint64(count + 1))
	size = (count + 1) * 16
	for k := int64(0); k < count; k++ {
		record, ok := tableMessageRecordScan(r, root, blobs)
		if !ok {
			return 0, false, false
		}
		size += record.size
	}
	extent := int64(0)
	complete = tableMessageExtent(r, root, &extent)
	size += tableRegionRound(tableRegionRound(int64(root.Size)) + extent)
	return size, complete, true
}
func tableMessageRegionMeasure(v *TableVocabulary, data []byte, root *TableTypeInfo, blobs int) int64 {
	var ignored TableReport
	r, count := tableMessageBatchOpen(v, data, &ignored)
	if count < 0 {
		return -1
	}
	total := int64(0)
	for i := int64(0); i < count; i++ {
		size, complete, ok := tableMessageBodyStorage(&r, root, blobs)
		if !ok {
			return -1
		}
		total += size
		if !complete {
			break
		}
	}
	return total
}
func tableMessageLoadInto(r TableMessageReader, t *TableTypeInfo, p unsafe.Pointer, size int64) (TableMessageReader, bool) {
	return t.LoadMessageBody(r, p)
}
func tableMessageRegionInto(r *TableMessageReader, root *TableTypeInfo, blobs int, region []byte, used *int64) (out unsafe.Pointer, ok bool) {
	count, ok := tableMessageNodeOpen(r)
	if !ok {
		r.Report.Malformed = true
		return nil, false
	}
	directoryBytes := (count + 1) * 16
	limit := int64(len(region))
	if *used > limit || directoryBytes > limit-*used {
		r.Report.Malformed = true
		return nil, false
	}
	base := unsafe.Pointer(&region[0])
	directory := unsafe.Slice((*TableNodeDirEntry)(unsafe.Add(base, *used)), int(count+1))
	*used += directoryBytes
	r.IndexBits = tableMessageBits(uint64(count + 1))
	nodes := TableNodeMap{Base: base, Entries: directory}
	recordsStart := r.Bits.Offset
	unknown := int32(0)
	for k := int64(0); k < count; k++ {
		record, good := tableMessageRecordScan(r, root, blobs)
		if !good {
			r.Report.Malformed = true
			return nil, false
		}
		entry := &directory[k+1]
		entry.TypeId = record.id
		if record.size <= 0 {
			entry.Offset = ^uint64(0)
			unknown++
			continue
		}
		if record.size > limit-*used {
			r.Report.Malformed = true
			return nil, false
		}
		entry.Offset = uint64(*used)
		p := unsafe.Add(base, *used)
		if t := root.NodeType(record.id); t != nil {
			t.Reset(p)
		} else {
			*(*TableBlob)(p) = TableBlob{Length: uint32(uint64(record.length))}
		}
		*used += record.size
	}
	fieldsStart := r.Bits.Offset
	walk := *r
	extent := int64(0)
	complete := tableMessageExtent(&walk, root, &extent)
	if !complete && tableMessageHasExtent(root) {
		r.Report.Malformed = true
		return nil, false
	}
	rootSize := tableRegionRound(tableRegionRound(int64(root.Size)) + extent)
	if rootSize > limit-*used {
		r.Report.Malformed = true
		return nil, false
	}
	directory[0] = TableNodeDirEntry{Offset: uint64(*used), TypeId: root.Id}
	out = unsafe.Add(base, *used)
	root.Reset(out)
	*used += rootSize
	nodes.Good = true
	r.Report.Unknown += unknown
	r.Nodes = nodes
	r.Bits.Offset = recordsStart
	for k := int64(0); k < count; k++ {
		if _, good := r.Bits.Get(r.Vocabulary.RefBits); !good {
			r.Report.Malformed = true
			return out, false
		}
		entry := directory[k+1]
		if entry.TypeId == tableBytesTypeId || entry.TypeId == tableStringTypeId {
			n, good := r.Bits.Get(32)
			if !good || !r.Bits.Align() {
				r.Report.Malformed = true
				return out, false
			}
			start := r.Bits.Offset / 8
			if !r.Bits.Skip(int64(n) * 8) {
				r.Report.Malformed = true
				return out, false
			}
			payload := r.Bits.Buffer[start : start+int64(n)]
			if entry.TypeId == tableStringTypeId && blobs&2 != 0 && !tableUtf8Valid(payload) {
				r.Report.Malformed = true
				return out, false
			}
			if entry.Offset != ^uint64(0) {
				copy(unsafe.Slice((*byte)(unsafe.Add(base, entry.Offset+8)), int(n)), payload)
			}
			continue
		}
		if entry.Offset == ^uint64(0) {
			if !tableMessageSkipBody(&r.Bits, r.Vocabulary, r.IndexBits, 0) {
				r.Report.Malformed = true
				return out, false
			}
			continue
		}
		t := root.NodeType(entry.TypeId)
		walk := *r
		extent := int64(0)
		if !tableMessageExtent(&walk, t, &extent) {
			r.Report.Malformed = true
			return out, false
		}
		*r, ok = tableMessageLoadInto(*r, t, unsafe.Add(base, entry.Offset), tableRegionRound(int64(t.Size))+extent)
		if !ok {
			return out, false
		}
	}
	if r.Bits.Offset != fieldsStart {
		r.Report.Malformed = true
		return out, false
	}
	*r, ok = tableMessageLoadInto(*r, root, out, rootSize)
	return out, ok
}
func tableMessageHasExtent(t *TableTypeInfo) bool {
	for i := range t.Fields {
		if tableMessageFieldHasExtent(&t.Fields[i]) {
			return true
		}
	}
	return false
}
func tableMessageFieldHasExtent(f *TableFieldInfo) bool {
	if f.List || f.Map {
		return true
	}
	if f.Pointer {
		return false
	}
	if f.Kind == 13 && f.Table != nil {
		return tableMessageHasExtent(f.Table())
	}
	if f.Kind == 15 && f.Arms != nil {
		u := f.Arms()
		for i := 1; i < len(u.Arms); i++ {
			if !u.Arms[i].Void && tableMessageFieldHasExtent(&u.Arms[i].Field) {
				return true
			}
		}
	}
	return false
}

const TableFixedForm uint8 = 3
const TableFixedHeaderBytes = 16
const TableFixedHashAt = 8

const (
	tableFixedCopy uint8 = iota
	tableFixedCount
	tableFixedText
	tableFixedOrdinal
	tableFixedWiden
	tableFixedConst
	tableFixedWidenF
	tableFixedBool
	tableFixedTag
)

const (
	tableFixedTextUtf8  uint8 = 1
	tableFixedTextWide  uint8 = 2
	tableFixedTextBytes uint8 = 3
)

const tableFixedNoGuard uint32 = 0xFFFFFFFF
const tableFixedEntryBytes int32 = 17

// THE LAYOUT'S OWN BOUNDS (mas-bandwidth/schema docs/FIXED-FORM-ALGORITHM.md §1.1). The header is
// the u32 entry count and nothing else. 65536 is the form's record body bound,
// which a DECLARED fixed table is held to at compile time and an untrusted
// peer's layout is held to here, so the two sides agree by construction. The
// depth is a bound on THIS READER'S WALK and not on the wire: the reference
// states 64 and every leg states the same number.
const tableFixedLayoutHeaderBytes int32 = 4
const tableFixedRecordMaxBytes uint32 = 65536
const tableFixedMaxDepth int32 = 64

// Arg is the guard's arm ordinal: tableFixedRun compares src[Guard] against
// it. Meta is a text entry's flavour (tableFixedTextUtf8/Wide/Bytes). They
// shared one lane until reference-fix 12; compiling a string under a union
// arm overwrote the guard with the flavour and the read skipped the string.
// tableFixedEntryBytes is the FILE layout entry (id+kind+size+children),
// not this in-memory plan row — Meta does not ride the wire.
// ArgW IS THE GUARD'S WIDTH IN BYTES (§5.2 THE GUARD'S WIDTH): a union tag is
// one, two, four or eight bytes, clamped 1..8, and 0 reads as 1. The guard is
// tested at that FULL width and never at its first byte — a foreign two-byte
// tag 0x0101 is not arm 1. Arg is the arm ordinal and carries NO BYTE LANE
// (§5.8 row 5): a 256-arm union's ordinal does not fit a byte.
type TableFixedEntry struct {
	Src, Dst, Size, Aux, Guard, Arg uint32
	// Guard2 / Arg2 / ArgW2 ARE THE OUTER TAG AN ARM INSIDE AN ARM ALSO ANSWERS
	// TO (mas-bandwidth/schema docs/FIXED-FORM-ALGORITHM.md §4.1): the entry runs only when BOTH tags
	// hold their ordinal. ArgW2 of zero is "no outer tag", so a plan that never
	// nests a union leaves the lane unset and the read is unchanged.
	Guard2, Arg2                         uint32
	Op, ArgW, DstSize, Sign, Meta, ArgW2 uint8
}

type TableFixedDst struct {
	Dst, Stride, Aux   uint32
	Counted, Arg, Meta uint8
}

type tableFixedPlan struct {
	Entries []TableFixedEntry
	Count   int32
	// Split is the number of UNGUARDED entries (mas-bandwidth/schema docs/FIXED-FORM-ALGORITHM.md
	// §4.1): the index the guarded half starts at, stated by the plan itself.
	Split int32
}

func tableFixedWidens(from, to uint8) bool {
	if from >= 6 && from <= 9 && to >= 6 && to <= 9 {
		return to > from
	}
	if from >= 2 && from <= 5 && to >= 2 && to <= 5 {
		return to > from
	}
	// THE FIXED-POINT RUNGS, signed 20..24 and unsigned 25..29: a fixed(I,F)
	// into a wider I at equal F is a LADDER widen and not a kind that moved
	// (mas-bandwidth/schema docs/FIXED-FORM-ALGORITHM.md §1, §5.1).
	if from >= 20 && from <= 24 && to >= 20 && to <= 24 {
		return to > from
	}
	if from >= 25 && from <= 29 && to >= 25 && to <= 29 {
		return to > from
	}
	return from == 10 && to == 11
}

// A WIDEN'S SIGN IS THE LADDER'S: the source sign-extends when the WRITER's
// kind is signed — i8..i64 and a SIGNED fixed(I,F), 20..24 — and zero-extends
// otherwise (§5.2).
func tableFixedSignedKind(kind uint8) bool {
	return (kind >= 2 && kind <= 5) || (kind >= 20 && kind <= 24)
}

// THE CLOSED KIND SET (mas-bandwidth/schema docs/FIXED-FORM-ALGORITHM.md §1): §3's own kinds 1..30,
// the no-payload variant 32, wstring 33, and the ONE kind this form's layout
// adds, the optional wrapper 35. 0 is no kind at all, 31 is §3's BODY framing
// escape and 34 is reserved: none of the three is a kind a declaration spells,
// so none is ever an entry's kind. A KIND OUTSIDE THIS SET IS A REFUSAL, not a
// leaf to step over — the form byte versions the kinds behind it, so a kind
// this build does not know names a FORM this reader never saw.
func tableFixedKindKnown(kind uint8) bool {
	if kind >= 1 && kind <= 30 {
		return true
	}
	return kind == 32 || kind == 33 || kind == 35
}

// tableFixedOrdinalWidth is the widths an ordinal — an enum's, a union tag's —
// is stored at.
func tableFixedOrdinalWidth(n uint32) bool { return n == 1 || n == 2 || n == 4 || n == 8 }

// tableFixedLeafSize answers whether a kind is a LEAF and, if it is, whether
// the size it states is one its kind admits (§1.2). Kind and size fix each
// other on this wire with ONE exception, stated here rather than left to be
// found: a bits(N) field rides at its DECLARED STORAGE WIDTH — four bytes for
// N <= 32 and eight above — under the unsigned integer kind its BIT COUNT
// picks, so kinds 6 and 7 admit 4 as well as their own width.
func tableFixedLeafSize(kind uint8, size uint32) (admitted, leaf bool) {
	leaf = true
	switch kind {
	case 1, 2: // bool, i8
		return size == 1, leaf
	case 3: // i16
		return size == 2, leaf
	case 4: // i32
		return size == 4, leaf
	case 5: // i64
		return size == 8, leaf
	case 6: // u8, and bits( 1 .. 8 )
		return size == 1 || size == 4, leaf
	case 7: // u16, and bits( 9 .. 16 )
		return size == 2 || size == 4, leaf
	case 8: // u32, and bits( 17 .. 32 )
		return size == 4, leaf
	case 9: // u64, flags, and bits( 33 .. 64 )
		return size == 8, leaf
	case 10: // f32
		return size == 4, leaf
	case 11: // f64
		return size == 8, leaf
	case 17: // a pointer index, which no fixed table carries
		return size == 4, leaf
	case 18, 19: // i128, u128
		return size == 16, leaf
	case 20, 25: // fixed8, ufixed8
		return size == 1, leaf
	case 21, 26:
		return size == 2, leaf
	case 22, 27:
		return size == 4, leaf
	case 23, 28:
		return size == 8, leaf
	case 24, 29:
		return size == 16, leaf
	case 32: // a variant, and an arm that holds nothing
		return size == 0, leaf
	}
	return true, false
}

// tableFixedRuns is whether an op advances src and dst together one byte at a
// time, which is the whole of what lets two adjacent entries become one.
func tableFixedRuns(op uint8) bool { return op == tableFixedCopy || op == tableFixedBool }

// THE GUARD'S WIDTH, clamped (§5.2): 0 reads as 1, and nothing above 8 is a
// width an ordinal is stored at.
func tableFixedArgWidth(w uint8) uint32 {
	if w == 0 {
		return 1
	}
	if w > 8 {
		return 8
	}
	return uint32(w)
}

// tableFixedTagAt loads the guard WHOLE, little-endian, at its own width. A
// one-byte compare fires arm 1 on a foreign 0x0101; this is the compare.
func tableFixedTagAt(src []byte, at uint32, w uint8) uint64 {
	n := tableFixedArgWidth(w)
	var v uint64
	for k := uint32(0); k < n; k++ {
		v |= uint64(src[at+k]) << (8 * k)
	}
	return v
}

// THE PLAN IS PARTITIONED (mas-bandwidth/schema docs/FIXED-FORM-ALGORITHM.md §4.1, §4.4, §5.9
// item 42): every UNGUARDED entry first, then every guarded one, and the
// split — the NUMBER OF UNGUARDED ENTRIES, the index the second half starts
// at, not a count of guarded ones — is a property of that order. The emitter
// lays entries down in field order, so a field past a union would land an
// unguarded entry behind a guarded one; the builders repair that here, each
// in its own half, and never coalesce across the split. The run loop still
// tests the guard per entry, which item 42 allows outright: what a leg may
// not do is skip the partition. tableFixedPartition stable-partitions the
// built entries in place and returns the split; a plan with no guarded entry
// has its split at the END, not at zero.
func tableFixedPartition(plan []TableFixedEntry, n int32) int32 {
	split := int32(0)
	for i := int32(0); i < n; i++ {
		if plan[i].Guard == tableFixedNoGuard {
			e := plan[i]
			copy(plan[split+1:i+1], plan[split:i])
			plan[split] = e
			split++
		}
	}
	return split
}

func tableFixedBuildPlan(emit func([]TableFixedEntry, uint32, uint32) int, n int) tableFixedPlan {
	raw := make([]TableFixedEntry, n)
	written := emit(raw, 0, 0)
	out := 0
	for i := 0; i < written; i++ {
		if out > 0 && raw[out-1].Op == raw[i].Op && tableFixedRuns(raw[i].Op) &&
			raw[out-1].Guard == raw[i].Guard && raw[out-1].Arg == raw[i].Arg &&
			raw[out-1].ArgW == raw[i].ArgW && raw[out-1].Meta == raw[i].Meta &&
			raw[out-1].Guard2 == raw[i].Guard2 && raw[out-1].Arg2 == raw[i].Arg2 &&
			raw[out-1].ArgW2 == raw[i].ArgW2 &&
			raw[out-1].Src+raw[out-1].Size == raw[i].Src &&
			raw[out-1].Dst+raw[out-1].Size == raw[i].Dst {
			raw[out-1].Size += raw[i].Size
			continue
		}
		raw[out] = raw[i]
		out++
	}
	n = out
	// The split is KEPT, not discarded (mas-bandwidth/schema docs/FIXED-FORM-ALGORITHM.md §4.1):
	// the plan states where its guarded half starts.
	split := tableFixedPartition(raw, int32(n))
	return tableFixedPlan{Entries: raw[:n], Count: int32(n), Split: split}
}

func tableFixedPut8(b []byte, v uint8)         { b[0] = v }
func tableFixedPut16(b []byte, v uint16)       { binary.LittleEndian.PutUint16(b, v) }
func tableFixedPut32(b []byte, v uint32)       { binary.LittleEndian.PutUint32(b, v) }
func tableFixedPut64(b []byte, v uint64)       { binary.LittleEndian.PutUint64(b, v) }
func tableFixedPutF32(b []byte, v float32)     { tableFixedPut32(b, math.Float32bits(v)) }
func tableFixedPutF64(b []byte, v float64)     { tableFixedPut64(b, math.Float64bits(v)) }
func tableFixedPut128(b []byte, lo, hi uint64) { tableFixedPut64(b, lo); tableFixedPut64(b[8:], hi) }
func tableFixedGet32(b []byte) uint32          { return binary.LittleEndian.Uint32(b) }
func tableFixedGet64(b []byte) uint64          { return binary.LittleEndian.Uint64(b) }

func tableFixedCopyRun(d, s []byte, n uint32) {
	if n == 0 {
		return
	}
	if n <= 16 {
		if n >= 8 {
			a := binary.LittleEndian.Uint64(s)
			b := binary.LittleEndian.Uint64(s[n-8:])
			binary.LittleEndian.PutUint64(d, a)
			binary.LittleEndian.PutUint64(d[n-8:], b)
		} else if n >= 4 {
			a := binary.LittleEndian.Uint32(s)
			b := binary.LittleEndian.Uint32(s[n-4:])
			binary.LittleEndian.PutUint32(d, a)
			binary.LittleEndian.PutUint32(d[n-4:], b)
		} else {
			d[0] = s[0]
			d[n>>1] = s[n>>1]
			d[n-1] = s[n-1]
		}
		return
	}
	copy(d[:n], s[:n])
}

func tableFixedRun(plan []TableFixedEntry, count int32, src, dst []byte, report *TableReport) string {
	// READ(plan, split, ...) (mas-bandwidth/schema docs/FIXED-FORM-ALGORITHM.md §4.4): the plan is
	// partitioned unguarded-first (§4.1), so the split is the first guarded
	// index; entries below it run WITHOUT a guard test and only the guarded
	// half from split on tests one.
	split := count
	for i := int32(0); i < count; i++ {
		if plan[i].Guard != tableFixedNoGuard {
			split = i
			break
		}
	}
	for i := int32(0); i < count; i++ {
		p := plan[i]
		// THE GUARD AT ITS FULL WIDTH, never its first byte (§5.2). Below the
		// split there is no guard to test (§4.4).
		if i >= split && p.Guard != tableFixedNoGuard && tableFixedTagAt(src, p.Guard, p.ArgW) != uint64(p.Arg) {
			continue
		}
		// AN ARM INSIDE AN ARM ANSWERS TO THE OUTER TAG TOO (§4.1): the entry
		// runs only when the second lane's tag holds its ordinal as well.
		if p.ArgW2 != 0 && tableFixedTagAt(src, p.Guard2, p.ArgW2) != uint64(p.Arg2) {
			continue
		}
		switch p.Op {
		case tableFixedCopy:
			tableFixedCopyRun(dst[p.Dst:], src[p.Src:], p.Size)
		case tableFixedTag:
			// A UNION TAG NAMING NO ARM LANDS AS None AND COUNTS UNKNOWN,
			// which is what form 1 does with an arm id it does not know
			// (mas-bandwidth/schema docs/SPEC-TABLES.md §4). Copied raw it would land as a
			// discriminant no variant spells, and every arm's guard would
			// then decline to fill it — a value that is neither None nor an
			// arm. Aux is the reader's own arm count.
			var tag uint64
			for k := uint32(0); k < p.Size; k++ {
				tag |= uint64(src[p.Src+k]) << (8 * k)
			}
			if tag > uint64(p.Aux) {
				tag = 0
				report.Unknown++
			}
			for k := uint32(0); k < p.Size; k++ {
				dst[p.Dst+k] = byte(tag >> (8 * k))
			}
		case tableFixedBool:
			// A GO bool IS NOT A BYTE. A Go true is the byte 1 (v == true,
			// array equality). if v is TESTB (nonzero) on amd64 and TBZ bit
			// 0 on arm64, so a hostile 2 reads true on one and false on the
			// other. The wire says nonzero is true (mas-bandwidth/schema docs/SPEC-TABLES.md §3);
			// normalise here (byte != 0 -> 1) and never copy.
			for k := uint32(0); k < p.Size; k++ {
				v := byte(0)
				if src[p.Src+k] != 0 {
					v = 1
				}
				dst[p.Dst+k] = v
			}
		case tableFixedCount:
			v := int32(tableFixedGet32(src[p.Src:]))
			if v < 0 {
				v = 0
				report.Clamped++
			} else if v > int32(p.Size) {
				v = int32(p.Size)
				report.Clamped++
			}
			binary.LittleEndian.PutUint32(dst[p.Dst:], uint32(v))
		case tableFixedText:
			unit := uint32(1)
			if p.Meta == tableFixedTextWide {
				unit = 2
			}
			capn := p.Size / unit
			v := int32(tableFixedGet32(src[p.Src:]))
			if v < 0 {
				v = 0
				report.Clamped++
			} else if uint32(v) > capn {
				v = int32(capn)
				report.Clamped++
			}
			// THE CONTENT RULES APPLY TO THE USED UNITS AND NOTHING ELSE, and a
			// violation REFUSES BY NAME, the verdict the packet reader gives
			// (mas-bandwidth/schema docs/FIXED-FORM-ALGORITHM.md §4.5, §5.4 fix 11, §5.8 row 8): the
			// length above CLAMPS and counts; the bytes it kept are checked now,
			// over v units and never over the span.
			if tableFixedTextIllFormed(p.Meta, uint32(v), src[p.Src+4:]) {
				return "text_ill_formed"
			}
			binary.LittleEndian.PutUint32(dst[p.Dst:], uint32(v))
			tableFixedCopyRun(dst[p.Aux:], src[p.Src+4:], p.Size)
			if p.Meta != tableFixedTextBytes && uint32(v) < capn {
				off := p.Aux + uint32(v)*unit
				dst[off] = 0
				if unit == 2 {
					dst[off+1] = 0
				}
			}
		case tableFixedOrdinal:
			// SIXTY-FOUR BITS. An ordinal rides at 1, 2, 4 or 8 bytes (§1.2);
			// read through a 32-bit temporary an eight-byte ordinal loses its
			// top four bytes, so a forged 0x1_0000_0001 would land as 1.
			// THE OP MOVES NOTHING (§5.4): a raw past the writer's set lands
			// None here, and tableFixedForgedBounds counts it once in the
			// BOUNDS pass, on the compiled plan as the storage clamp counts the
			// identity plan's own forged tag (mas-bandwidth/schema docs/FIXED-FORM-ALGORITHM.md §5.4,
			// §5.8 row 12, fix 27).
			raw := tableFixedTagAt(src, p.Src, uint8(p.Size))
			p16 := (*uint16)(unsafe.Add(unsafe.Pointer(&plan[0]), uintptr(p.Aux)))
			table := unsafe.Slice(p16, int(*p16)+1)
			var v uint32
			if raw != 0 && raw <= uint64(table[0]) {
				v = uint32(table[raw])
			}
			switch p.DstSize {
			case 1:
				dst[p.Dst] = uint8(v)
			case 2:
				binary.LittleEndian.PutUint16(dst[p.Dst:], uint16(v))
			case 8:
				binary.LittleEndian.PutUint64(dst[p.Dst:], uint64(v))
			default:
				binary.LittleEndian.PutUint32(dst[p.Dst:], v)
			}
		case tableFixedWiden:
			var raw uint64
			for i := uint32(0); i < p.Size; i++ {
				raw |= uint64(src[p.Src+i]) << (8 * i)
			}
			if p.Sign != 0 {
				bits := p.Size * 8
				top := uint64(1) << (bits - 1)
				if raw&top != 0 {
					raw |= ^((top << 1) - 1)
				}
			}
			for i := uint8(0); i < p.DstSize; i++ {
				dst[p.Dst+uint32(i)] = byte(raw >> (8 * i))
			}
			report.Widened++
		case tableFixedWidenF:
			bits := tableFixedGet32(src[p.Src:])
			var widened uint64
			if bits&0x7f800000 == 0x7f800000 {
				// THE ALL-ONES EXPONENT IS ASSEMBLED BY HAND (mas-bandwidth/schema docs/SPEC-TABLES.md
				// §3.4, §21.2; the packet runtime's float-widen helper): the hardware
				// f32->f64 conversion QUIETS a signalling NaN and can drop a
				// payload bit, so the sign, the all-ones exponent and the 23-bit
				// mantissa shifted left by 29 are carried exactly and the quiet
				// bit stays as the writer wrote it.
				widened = uint64(bits>>31)<<63 | 0x7ff0000000000000 | uint64(bits&0x7fffff)<<29
			} else {
				widened = math.Float64bits(float64(math.Float32frombits(bits)))
			}
			tableFixedPut64(dst[p.Dst:], widened)
			report.Widened++
		case tableFixedConst:
			aux := p.Aux
			for i := uint32(0); i < p.Size; i++ {
				dst[p.Dst+i] = byte(aux >> (8 * i))
			}
			// THE OP MOVES NOTHING (§5.4): the unguarded None const lands None,
			// and a raw tag past the writer's arm count (this entry's DstSize) is
			// counted once by tableFixedForgedBounds, the BOUNDS pass, on the
			// compiled plan as the storage clamp counts the identity plan's own
			// forged tag (mas-bandwidth/schema docs/FIXED-FORM-ALGORITHM.md §5.4, §5.8 row 12, fix 27).
			// tableFixedSrcEnd gives this one entry a source reach, so the
			// record bound has already refused a plan that would read past it.
		}
	}
	return ""
}

// tableFixedForgedBounds is the BOUNDS pass's count of a forged ordinal or union
// tag (§5.4, fix 27): a raw ordinal past the writer's variant count, or a raw
// union tag past the writer's arm count, is landed None by the ordinal/const
// op — which moves nothing — and counted HERE, once per field, on the compiled
// plan exactly as the identity plan's storage clamp counts its own forged tag.
// The identity plan carries no ordinal or unguarded const entry (its union
// tag and leaves are copy), so this pass is silent for it, and the writer's
// count the storage clamp cannot see — the remap table's length word, or the
// entry's DstSize — is why the count lives in the plan-aware pass here and not
// in the op (mas-bandwidth/schema docs/FIXED-FORM-ALGORITHM.md §5.4, §5.8 row 12).
func tableFixedForgedBounds(plan []TableFixedEntry, count int32, src []byte, report *TableReport) {
	for i := int32(0); i < count; i++ {
		p := plan[i]
		// THE GUARD AT ITS FULL WIDTH, matching tableFixedRun (§5.2): an entry
		// whose guard does not match never lands, so it never counts.
		if p.Guard != tableFixedNoGuard && tableFixedTagAt(src, p.Guard, p.ArgW) != uint64(p.Arg) {
			continue
		}
		// AN ARM INSIDE AN ARM ANSWERS TO THE OUTER TAG TOO (§4.1): an entry
		// whose second lane does not hold never lands, so it never counts.
		if p.ArgW2 != 0 && tableFixedTagAt(src, p.Guard2, p.ArgW2) != uint64(p.Arg2) {
			continue
		}
		switch p.Op {
		case tableFixedOrdinal:
			raw := tableFixedTagAt(src, p.Src, uint8(p.Size))
			p16 := (*uint16)(unsafe.Add(unsafe.Pointer(&plan[0]), uintptr(p.Aux)))
			table := unsafe.Slice(p16, int(*p16)+1)
			if raw != 0 && raw > uint64(table[0]) {
				report.Clamped++
			}
		case tableFixedConst:
			if p.Aux == 0 && p.DstSize != 0 && p.Guard == tableFixedNoGuard {
				var raw uint64
				for k := uint32(0); k < p.Size; k++ {
					raw |= uint64(src[p.Src+k]) << (8 * k)
				}
				if raw > uint64(p.DstSize) {
					report.Clamped++
				}
			}
		}
	}
}

// tableFixedTextIllFormed reports whether a text payload's USED units are the
// text its kind says (mas-bandwidth/schema docs/FIXED-FORM-ALGORITHM.md §4.5, §5.4 fix 11): UTF-8
// with no zero byte for string, paired non-zero UTF-16 code units for wstring.
// bytes(N) carries no text rule at all, and slack past the used units is
// unspecified and never a refusal (mas-bandwidth/schema docs/SPEC-TABLES.md §3.4). The used argument
// is the clamped length in the flavour's own units. THE STRING RULE IS THE
// PACKET READER'S EXACTLY: unicode/utf8.Valid over the used bytes, then no
// interior zero (mas-bandwidth/schema internal/codegen/golang/functions.go, the TString arm), so
// every ill-formed sequence utf8 refuses — overlong, surrogate, past U+10FFFF,
// an invalid lead — refuses here too and not only structural truncation.
func tableFixedTextIllFormed(meta uint8, used uint32, p []byte) bool {
	switch meta {
	case tableFixedTextUtf8:
		if !utf8.Valid(p[:used]) {
			return true
		}
		for _, c := range p[:used] {
			if c == 0 {
				return true
			}
		}
	case tableFixedTextWide:
		for i := uint32(0); i < used; i++ {
			u := uint16(p[i*2]) | uint16(p[i*2+1])<<8
			switch {
			case u == 0:
				return true
			case u >= 0xD800 && u <= 0xDBFF:
				if i+1 >= used {
					return true
				}
				lo := uint16(p[(i+1)*2]) | uint16(p[(i+1)*2+1])<<8
				if lo < 0xDC00 || lo > 0xDFFF {
					return true
				}
				i++
			case u >= 0xDC00 && u <= 0xDFFF:
				return true
			}
		}
	}
	return false
}

// tableFixedTextRefusal is the text CONTENT refusal as a PRE-SCAN of the plan's
// text entries, run before the caller's storage is touched. It walks each text
// entry under its own guard, clamps its length exactly as the scatter will, and
// answers the one name an ill-formed payload refuses with
// (mas-bandwidth/schema docs/FIXED-FORM-ALGORITHM.md §4.5, §5.4 fix 11, §5.8 row 8). §5.8: "REFUSE
// is total: no counter moves, nothing is decoded, and not one destination byte
// is written — the prefill included", so the check lives here rather than only
// inside the scatter, where an earlier entry's write would already have landed.
// It writes nothing and moves no counter.
func tableFixedTextRefusal(plan []TableFixedEntry, count int32, src []byte) string {
	for i := int32(0); i < count; i++ {
		p := plan[i]
		if p.Op != tableFixedText {
			continue
		}
		// THE GUARD AT ITS FULL WIDTH, never its first byte (§5.2): an arm's
		// entry runs only under its own tag, and one that does not run cannot
		// refuse.
		if p.Guard != tableFixedNoGuard && tableFixedTagAt(src, p.Guard, p.ArgW) != uint64(p.Arg) {
			continue
		}
		unit := uint32(1)
		if p.Meta == tableFixedTextWide {
			unit = 2
		}
		capn := p.Size / unit
		v := int32(tableFixedGet32(src[p.Src:]))
		if v < 0 {
			v = 0
		} else if uint32(v) > capn {
			v = int32(capn)
		}
		if tableFixedTextIllFormed(p.Meta, uint32(v), src[p.Src+4:]) {
			return "text_ill_formed"
		}
	}
	return ""
}

type tableFixedLayoutEntry struct {
	Id             uint64
	Size, Children uint32
	Kind           uint8
}
type tableFixedLayoutView struct {
	Bytes []byte
	Count int32
}

// AN INDEX PAST THE ENTRIES IS ANSWERED, NOT READ. Every index into a layout is
// arithmetic over child counts a STRANGER wrote, so the one place that can hold
// the whole walk inside the buffer is the one place that touches it. An
// out-of-range index answers kind 0xFF, which is a kind no declaration has and
// nothing matches, so the walk that asked for it finds nothing and moves on.
func tableFixedEntryAt(b tableFixedLayoutView, i int32) tableFixedLayoutEntry {
	if b.Bytes == nil || i < 0 || i >= b.Count {
		return tableFixedLayoutEntry{Kind: 0xFF}
	}
	e := b.Bytes[int64(tableFixedLayoutHeaderBytes)+int64(i)*int64(tableFixedEntryBytes):]
	return tableFixedLayoutEntry{
		Id:       tableFixedGet64(e),
		Kind:     e[8],
		Size:     tableFixedGet32(e[9:]),
		Children: tableFixedGet32(e[13:]),
	}
}

// tableFixedSubtree is how many entries the subtree rooted at i occupies, so a
// walk steps over a child it does not want without knowing what is in it.
//
// ITERATIVE ON PURPOSE (mas-bandwidth/schema docs/FIXED-FORM-ALGORITHM.md §1.1). A layout is a
// stranger's bytes, so a chain of single-child entries is a stack depth the WIRE
// gets to choose; this walk gives it none. The pending counter is the pre-order
// walk's own arithmetic: one entry is owed at the start, each entry owes its
// children, and the subtree ends when nothing is owed.
func tableFixedSubtree(b tableFixedLayoutView, i int32) int32 {
	if i < 0 || i >= b.Count {
		return 1
	}
	pending := int64(1)
	n := int32(0)
	at := i
	for pending > 0 && at < b.Count {
		pending--
		n++
		pending += int64(tableFixedEntryAt(b, at).Children)
		at++
		if pending > int64(b.Count) {
			break
		}
	}
	return n
}

func tableFixedUnionArmBytes(b tableFixedLayoutView, i int32) uint32 {
	e := tableFixedEntryAt(b, i)
	var widest uint32
	at := i + 1
	for k := uint32(0); k < e.Children && at < b.Count; k++ {
		a := tableFixedEntryAt(b, at)
		if a.Size > widest {
			widest = a.Size
		}
		at += tableFixedSubtree(b, at)
	}
	return widest
}

// ---- THE LAYOUT'S OWN VALIDATION, RULE BY NAMED RULE -----------------------
//
// A LAYOUT ARRIVES FROM AN UNTRUSTED PEER and it is the one structure a reader
// must parse before it knows anything at all, so every rule below runs BEFORE a
// single record byte is touched and each refuses under ITS OWN NAME rather than
// under one word for all of them (mas-bandwidth/schema docs/FIXED-FORM-ALGORITHM.md §1.1).
//
// NOR IS THERE A CYCLE RULE, because a pre-order walk cannot express a cycle: an
// entry's children ARE THE ENTRIES THAT FOLLOW IT, so a child's index is always
// higher than its parent's, the layout is finite, and there is no back reference
// for a cycle to be made of. The tree-closure rule is what bounds the walk, and
// the depth rule is what bounds the reader's stack.
type tableFixedCheck struct {
	layout tableFixedLayoutView
	why    string
}

// Keep the FIRST reason and stop: the order of the rules is load-bearing, so the
// reason a reader reports is the first one the layout broke.
func (c *tableFixedCheck) fail(why string) {
	if c.why == "" {
		c.why = why
	}
}

// tableFixedCheckEntry validates the subtree rooted at i and answers how many
// entries it occupies, which is the same arithmetic tableFixedSubtree does and
// is why that walk is safe to run afterwards and only afterwards.
func tableFixedCheckEntry(c *tableFixedCheck, i, depth int32) int32 {
	if c.why != "" {
		return 0
	}
	if i < 0 || i >= c.layout.Count {
		c.fail("layout_tree_unclosed")
		return 0
	}
	if depth > tableFixedMaxDepth {
		c.fail("layout_too_deep")
		return 0
	}
	e := tableFixedEntryAt(c.layout, i)
	// THE CLOSED KIND SET, FIRST: a kind outside it is a layout of another form
	// and is refused whole, never walked and never stepped over.
	if !tableFixedKindKnown(e.Kind) {
		c.fail("layout_kind_unknown")
		return 0
	}
	if e.Size > tableFixedRecordMaxBytes {
		c.fail("layout_record_too_large")
		return 0
	}

	// THE CHILDREN FIRST, in the pre-order the layout is written in.
	at := i + 1
	var sum uint64
	var widest, firstSize, secondSize, firstChildren uint32
	var firstKind uint8
	kidsAreVariants := true
	for k := uint32(0); k < e.Children; k++ {
		child := at
		used := tableFixedCheckEntry(c, child, depth+1)
		if c.why != "" {
			return 0
		}
		ce := tableFixedEntryAt(c.layout, child)
		if k == 0 {
			firstSize, firstKind, firstChildren = ce.Size, ce.Kind, ce.Children
		}
		if k == 1 {
			secondSize = ce.Size
		}
		if ce.Kind != 32 {
			kidsAreVariants = false
		}
		// THE SUM IS 64 BITS precisely so a u32 that overflows is CAUGHT rather
		// than wrapped into a small number that then agrees with its parent.
		sum += uint64(ce.Size)
		if ce.Size > widest {
			widest = ce.Size
		}
		if sum > uint64(tableFixedRecordMaxBytes) {
			c.fail("layout_record_too_large")
			return 0
		}
		at += used
	}

	admitted, leaf := tableFixedLeafSize(e.Kind, e.Size)
	if !admitted {
		c.fail("layout_size_mismatch")
		return 0
	}
	if leaf {
		if e.Children != 0 {
			c.fail("layout_kind_invalid")
			return 0
		}
		return at - i
	}
	switch e.Kind {
	case 13: // a TABLE: its size is the SUM of its fields'
		if uint64(e.Size) != sum {
			c.fail("layout_size_mismatch")
			return 0
		}
	case 35: // the OPTIONAL WRAPPER: one child, one present byte in front of it
		if e.Children != 1 {
			c.fail("layout_kind_invalid")
			return 0
		}
		if uint64(e.Size) != sum+1 {
			c.fail("layout_size_mismatch")
			return 0
		}
	case 14: // an ARRAY: a whole number of elements, behind a count or not
		if e.Children != 1 {
			c.fail("layout_kind_invalid")
			return 0
		}
		if firstSize == 0 {
			c.fail("layout_size_mismatch")
			return 0
		}
		bare := e.Size%firstSize == 0
		counted := e.Size >= 4 && (e.Size-4)%firstSize == 0
		if !bare && !counted {
			c.fail("layout_size_mismatch")
			return 0
		}
	case 16: // an ENUM-KEYED array: the KEY ENUM then the ELEMENT, every slot written
		if e.Children != 2 {
			c.fail("layout_kind_invalid")
			return 0
		}
		if firstKind != 30 {
			c.fail("layout_kind_invalid")
			return 0
		}
		if secondSize == 0 || e.Size%secondSize != 0 {
			c.fail("layout_size_mismatch")
			return 0
		}
		// AT LEAST one slot per variant. Not exactly one: an enum widened by an
		// explicit max has more slots than it has names, and the layout carries
		// only the names.
		if e.Size/secondSize < firstChildren {
			c.fail("layout_size_mismatch")
			return 0
		}
	case 15: // a UNION: the TAG at its own width, then the WIDEST ARM
		if e.Children == 0 {
			c.fail("layout_kind_invalid")
			return 0
		}
		if e.Size <= widest {
			c.fail("layout_size_mismatch")
			return 0
		}
		if !tableFixedOrdinalWidth(e.Size - widest) {
			c.fail("layout_size_mismatch")
			return 0
		}
	case 30: // an ENUM: the ordinal's storage width, and its children are VARIANTS
		if !tableFixedOrdinalWidth(e.Size) {
			c.fail("layout_size_mismatch")
			return 0
		}
		if e.Children != 0 && !kidsAreVariants {
			c.fail("layout_kind_invalid")
			return 0
		}
	case 12: // string(N): the length, then N bytes
		if e.Children != 0 {
			c.fail("layout_kind_invalid")
			return 0
		}
		if e.Size < 4 {
			c.fail("layout_size_mismatch")
			return 0
		}
	case 33: // wstring(N): the length in CODE UNITS, then 2N bytes
		if e.Children != 0 {
			c.fail("layout_kind_invalid")
			return 0
		}
		if e.Size < 4 || (e.Size-4)%2 != 0 {
			c.fail("layout_size_mismatch")
			return 0
		}
	default:
		// Every kind of the closed set is either a leaf above or a case here, so
		// this is unreachable — and it refuses rather than admits, because a
		// kind that reached it is a kind the two lists disagree about.
		c.fail("layout_kind_unknown")
		return 0
	}
	return at - i
}

func tableFixedTagBytes(b tableFixedLayoutView, i int32) uint32 {
	return tableFixedEntryAt(b, i).Size - tableFixedUnionArmBytes(b, i)
}

// tableFixedParseLayout is the WHOLE of what a reader trusts a layout on. It
// answers the view and a REASON BY NAME — empty when the layout passed every
// rule — and the caller reports that reason. A layout that fails any rule SETS
// NOTHING: no view, no plan, and no counter moved.
//
// THE ORDER IS LOAD-BEARING (mas-bandwidth/schema docs/FIXED-FORM-ALGORITHM.md §1.1): rule 1; the
// root's kind and size; then the walk — index in range (5), depth (7), kind
// known (2), own size (6), the children, then the size and shape rules (3, 4);
// and last that the walk consumed exactly the entries (5).
func tableFixedParseLayout(bytes []byte) (tableFixedLayoutView, string) {
	var out tableFixedLayoutView
	// THE RESIDUE: bytes that are not a layout at all — fewer than a header's
	// worth of them — are layout_malformed and not one of the seven.
	if int32(len(bytes)) < tableFixedLayoutHeaderBytes {
		return out, "layout_malformed"
	}
	// 1. THE ENTRY COUNT FITS THE LAYOUT LENGTH EXACTLY
	count := tableFixedGet32(bytes)
	if count == 0 || int64(count)*int64(tableFixedEntryBytes)+int64(tableFixedLayoutHeaderBytes) != int64(len(bytes)) {
		return out, "layout_count_mismatch"
	}
	view := tableFixedLayoutView{Bytes: bytes, Count: int32(count)}
	// 2. THE ROOT IS A TABLE, and its size is the record's body
	root := tableFixedEntryAt(view, 0)
	if root.Kind != 13 {
		return out, "layout_kind_invalid"
	}
	if root.Size == 0 || root.Size > tableFixedRecordMaxBytes {
		return out, "layout_record_too_large"
	}
	// 3. EVERY KIND IN THE CLOSED SET AND USED AS ITS DEFINITION ALLOWS, EVERY
	//    SIZE THE ONE ITS CHILDREN ACCOUNT FOR, NOTHING PAST THE WALK'S BOUND
	c := tableFixedCheck{layout: view}
	used := tableFixedCheckEntry(&c, 0, 0)
	if c.why != "" {
		return out, c.why
	}
	// 4. THE PRE-ORDER WALK CONSUMES EXACTLY THE ENTRIES: the tree closes and
	//    the layout has nothing left over
	if used != view.Count {
		return out, "layout_tree_unclosed"
	}
	return view, ""
}

type tableFixedCompiler struct {
	plan                  []TableFixedEntry
	capacity, count, pool int32
	overflow              bool
	// tooLarge is ONE ENTRY PAST THE WRITER'S RECORD, which refuses the plan
	// WHOLE under layout_record_too_large (§5.2) and never lands a short read.
	tooLarge bool
	// record is the WRITER's declared root size, the bound every entry's
	// source extent is held to.
	record uint32
	// argW is the CURRENT union's tag width, stamped onto every guarded push.
	argW   uint8
	report *TableReport
}

// tableFixedSrcEnd is the last source byte, exclusive, an entry reads — the
// guard included, because a guarded entry loads the tag before anything else.
func tableFixedSrcEnd(e TableFixedEntry) uint64 {
	var end uint64
	switch e.Op {
	case tableFixedConst:
		end = 0 // a constant reads no source at all
		if e.Aux == 0 && e.DstSize != 0 {
			// EXCEPT THE UNION'S None CONST, which reads the writer's raw tag
			// to count a clamp past DstSize arms (schema#1254). It has a source
			// reach, so one past the writer's record refuses the plan whole
			// like every other entry — and the read loop needs no bound of its
			// own.
			end = uint64(e.Src) + uint64(e.Size)
		}
	case tableFixedCount:
		end = uint64(e.Src) + 4 // Size is the BOUND, not a byte count
	case tableFixedText:
		end = uint64(e.Src) + 4 + uint64(e.Size)
	default:
		end = uint64(e.Src) + uint64(e.Size)
	}
	if e.Guard != tableFixedNoGuard {
		if g := uint64(e.Guard) + uint64(tableFixedArgWidth(e.ArgW)); g > end {
			end = g
		}
	}
	// THE OUTER TAG IS READ BEFORE THE ENTRY TOO (§4.1), so its bytes are part
	// of the entry's source reach.
	if e.ArgW2 != 0 {
		if g := uint64(e.Guard2) + uint64(tableFixedArgWidth(e.ArgW2)); g > end {
			end = g
		}
	}
	return end
}

func tableFixedPush(c *tableFixedCompiler, e TableFixedEntry) {
	if e.Guard != tableFixedNoGuard {
		e.ArgW = uint8(tableFixedArgWidth(c.argW))
	}
	// ONE ENTRY PAST THE WRITER'S RECORD REFUSES THE PLAN WHOLE (§5.2). The
	// bound is the writer's declared root size and not this reader's: an entry
	// that reached past it would read the NEXT record's bytes.
	if c.record != 0 && tableFixedSrcEnd(e) > uint64(c.record) {
		c.tooLarge = true
		return
	}
	room := c.capacity - (c.pool+int32(unsafe.Sizeof(TableFixedEntry{}))-1)/int32(unsafe.Sizeof(TableFixedEntry{}))
	if c.count >= room {
		c.overflow = true
		return
	}
	c.plan[c.count] = e
	c.count++
}

// tableFixedRemapMax is the longest remap table the pool's u16 length word can
// name. A writer's variant count above it is a layout this reader cannot plan.
const tableFixedRemapMax uint32 = 0xFFFF

func tableFixedLayTable(c *tableFixedCompiler, values []uint16, n int32) uint32 {
	bytes := (n + 1) * 2
	total := int32(unsafe.Sizeof(TableFixedEntry{})) * c.capacity
	c.pool += bytes
	if total-c.pool < c.count*int32(unsafe.Sizeof(TableFixedEntry{})) {
		c.overflow = true
		return 0
	}
	at := uint32(total - c.pool)
	dst := unsafe.Slice((*uint16)(unsafe.Add(unsafe.Pointer(&c.plan[0]), uintptr(at))), n+1)
	dst[0] = uint16(n)
	copy(dst[1:], values[:n])
	return at
}

// census is whether THIS entry is the first time the peer's field is seen:
// an array's element subtree is compiled once per element and the unknown
// count is ONCE PER FIELD PER PEER (§5.4), so only element 0 censuses.
func tableFixedMatchChildren(c *tableFixedCompiler, theirs tableFixedLayoutView, ti int32, theirAt uint32, mine tableFixedLayoutView, mi int32, dst []TableFixedDst, myAt, guard uint32, arg uint32, census bool) {
	te := tableFixedEntryAt(theirs, ti)
	me := tableFixedEntryAt(mine, mi)
	myChild := mi + 1
	for k := uint32(0); k < me.Children; k++ {
		mc := tableFixedEntryAt(mine, myChild)
		theirChild := ti + 1
		theirOff := theirAt
		for j := uint32(0); j < te.Children; j++ {
			tc := tableFixedEntryAt(theirs, theirChild)
			if tc.Id == mc.Id {
				tableFixedCompileEntry(c, theirs, theirChild, theirOff, mine, myChild, dst, myAt, guard, arg, census)
				break
			}
			theirOff += tc.Size
			theirChild += tableFixedSubtree(theirs, theirChild)
		}
		myChild += tableFixedSubtree(mine, myChild)
	}
	tcAt := ti + 1
	for j := uint32(0); j < te.Children; j++ {
		tc := tableFixedEntryAt(theirs, tcAt)
		named := false
		mcAt := mi + 1
		for k := uint32(0); k < me.Children; k++ {
			if tableFixedEntryAt(mine, mcAt).Id == tc.Id {
				named = true
				break
			}
			mcAt += tableFixedSubtree(mine, mcAt)
		}
		if !named && census && c.report != nil {
			c.report.Unknown++
		}
		tcAt += tableFixedSubtree(theirs, tcAt)
	}
}

func tableFixedCompileEntry(c *tableFixedCompiler, theirs tableFixedLayoutView, ti int32, theirAt uint32, mine tableFixedLayoutView, mi int32, dst []TableFixedDst, myAt, guard uint32, arg uint32, census bool) {
	te := tableFixedEntryAt(theirs, ti)
	me := tableFixedEntryAt(mine, mi)
	d := dst[mi]
	at := myAt + d.Dst
	auxAt := myAt + d.Aux
	if te.Kind != me.Kind && !(me.Kind == 35) {
		if tableFixedWidens(te.Kind, me.Kind) {
			e := TableFixedEntry{Src: theirAt, Dst: at, Size: te.Size, DstSize: uint8(me.Size), Guard: guard, Arg: arg}
			if te.Kind == 10 {
				e.Op = tableFixedWidenF
			} else {
				e.Op = tableFixedWiden
			}
			if tableFixedSignedKind(te.Kind) {
				e.Sign = 1
			}
			tableFixedPush(c, e)
			return
		}
		if c.report != nil {
			c.report.KindMismatch++
		}
		return
	}
	// T INTO ?T (§5.2 EMIT, bill §12.8): the reader wrapped a value the writer
	// carried bare. The PRESENT byte is an UNGUARDED constant 1 at the
	// wrapper's aux lane, and the payload is compiled against the writer's own
	// entry under the same guard and ordinal. It is not a kind that moved.
	if me.Kind == 35 && te.Kind != 35 {
		tableFixedPush(c, TableFixedEntry{Dst: auxAt, Size: 1, Aux: 1, Guard: guard, Op: tableFixedConst, Arg: arg})
		tableFixedCompileEntry(c, theirs, ti, theirAt, mine, mi+1, dst, myAt, guard, arg, census)
		return
	}
	switch me.Kind {
	case 35:
		tableFixedPush(c, TableFixedEntry{Src: theirAt, Dst: auxAt, Size: 1, Guard: guard, Op: tableFixedBool, Arg: arg})
		tableFixedCompileEntry(c, theirs, ti+1, theirAt+1, mine, mi+1, dst, myAt, guard, arg, census)
	case 13:
		tableFixedMatchChildren(c, theirs, ti, theirAt, mine, mi, dst, at, guard, arg, census)
	case 14:
		tel := tableFixedEntryAt(theirs, ti+1)
		mel := tableFixedEntryAt(mine, mi+1)
		head := uint32(0)
		if d.Counted != 0 {
			head = 4
		}
		var theirN, myN uint32
		if tel.Size != 0 {
			theirN = (te.Size - head) / tel.Size
		}
		if mel.Size != 0 {
			myN = (me.Size - head) / mel.Size
		}
		theirBase := theirAt + head
		n := theirN
		if myN < n {
			n = myN
		}
		if d.Counted != 0 {
			// THE COUNT'S BOUND IS THE WRITER'S their_n (§5.2 EMIT kind 14,
			// §5.3 step 11: BOUNDS runs against the PLAN's bounds). The
			// reader's own bound is the wrong number: a forged 7 from a writer
			// bounded at 4 must land 4 and COUNT, not be admitted because this
			// reader grew to 8. n is their_n held to this reader's storage,
			// which is their_n itself on every legal widening.
			tableFixedPush(c, TableFixedEntry{Src: theirAt, Dst: auxAt, Size: n, Guard: guard, Op: tableFixedCount, Arg: arg})
		}
		for i := uint32(0); i < n; i++ {
			tableFixedCompileEntry(c, theirs, ti+1, theirBase+i*tel.Size, mine, mi+1, dst, at+i*d.Stride, guard, arg, census && i == 0)
		}
	case 16:
		tkey := tableFixedEntryAt(theirs, ti+1)
		mkey := tableFixedEntryAt(mine, mi+1)
		tel := ti + 1 + tableFixedSubtree(theirs, ti+1)
		mel := mi + 1 + tableFixedSubtree(mine, mi+1)
		tee := tableFixedEntryAt(theirs, tel)
		for k := uint32(0); k < mkey.Children; k++ {
			keyId := tableFixedEntryAt(mine, mi+2+int32(k)).Id
			for j := uint32(0); j < tkey.Children; j++ {
				if tableFixedEntryAt(theirs, ti+2+int32(j)).Id != keyId {
					continue
				}
				tableFixedCompileEntry(c, theirs, tel, theirAt+j*tee.Size, mine, mel, dst, at+k*d.Stride, guard, arg, census && k == 0)
				break
			}
		}
	case 15:
		theirTag := tableFixedTagBytes(theirs, ti)
		myTag := tableFixedTagBytes(mine, mi)
		// THE TAG'S "NONE" GOES DOWN FIRST AND UNGUARDED, and it is pushed
		// BEFORE c.argW is retuned below so it is stamped at the OUTER width:
		// None answers to the OUTER tag (bill §12.7). Every tag value below is
		// written under THEIR tag's guard, so a record naming an arm this build
		// does not have — or a tag past the writer's arm set entirely — landed
		// no tag at all from the plan and was answered by the prefill. That
		// answer was right and silent: DstSize carries THE WRITER'S ARM COUNT
		// for this one entry, and the read loop counts a clamp for a raw tag
		// past that set, so the compiled plan counts what the identity plan's
		// decode bound counts (schema#1254, §5.4, §5.8 row 12). Entries apply in
		// push order, so the arm that matches overwrites this one and it stands
		// when none does.
		none := TableFixedEntry{Src: theirAt, Dst: auxAt, Size: myTag, Guard: guard, Op: tableFixedConst, Arg: arg}
		if te.Children > 0 && te.Children <= 255 {
			none.DstSize = uint8(te.Children)
		}
		tableFixedPush(c, none)
		// THE WRITER'S TAG WIDTH IS THE GUARD'S (§5.2 THE GUARD'S WIDTH): every
		// entry pushed beneath this union is compared at it, whole.
		savedW := c.argW
		c.argW = 1
		if theirTag >= 1 && theirTag <= 8 {
			c.argW = uint8(theirTag)
		}
		myArm := mi + 1
		for k := uint32(0); k < me.Children; k++ {
			ma := tableFixedEntryAt(mine, myArm)
			theirArm := ti + 1
			for j := uint32(0); j < te.Children; j++ {
				ta := tableFixedEntryAt(theirs, theirArm)
				if ta.Id == ma.Id {
					tableFixedPush(c, TableFixedEntry{Src: theirAt, Dst: auxAt, Size: myTag, Aux: k + 1, Guard: theirAt, Op: tableFixedConst, Arg: j + 1})
					tableFixedCompileEntry(c, theirs, theirArm, theirAt+theirTag, mine, myArm, dst, at, theirAt, j+1, census)
					break
				}
				theirArm += tableFixedSubtree(theirs, theirArm)
			}
			myArm += tableFixedSubtree(mine, myArm)
		}
		c.argW = savedW
	case 30:
		// A GROWN ORDINAL WIDTH IS A WIDEN, unsigned, and it counts widened
		// (§5.2 EMIT kind 30, §5.4). Only a SAME-WIDTH ordinal takes the remap
		// table.
		if te.Size < me.Size {
			tableFixedPush(c, TableFixedEntry{Src: theirAt, Dst: at, Size: te.Size, Guard: guard,
				Op: tableFixedWiden, Arg: arg, DstSize: uint8(me.Size)})
			return
		}
		// THE TABLE IS AS LONG AS THE WRITER'S VARIANT COUNT (§5.2), not 255:
		// capped at 255 a 300-variant writer's variant 299 read as out of the
		// set and landed None.
		n := te.Children
		if n > tableFixedRemapMax {
			c.tooLarge = true
			return
		}
		m := make([]uint16, n)
		for j := uint32(0); j < n; j++ {
			vid := tableFixedEntryAt(theirs, ti+1+int32(j)).Id
			var landed uint16
			for k := uint32(0); k < me.Children; k++ {
				if tableFixedEntryAt(mine, mi+1+int32(k)).Id == vid {
					landed = uint16(k + 1)
					break
				}
			}
			m[j] = landed
		}
		e := TableFixedEntry{Src: theirAt, Dst: at, Size: te.Size, Guard: guard, Op: tableFixedOrdinal, Arg: arg, DstSize: uint8(me.Size)}
		e.Aux = tableFixedLayTable(c, m, int32(n))
		tableFixedPush(c, e)
	case 12, 33:
		units := me.Size - 4
		if te.Size-4 < units {
			units = te.Size - 4
		}
		tableFixedPush(c, TableFixedEntry{Src: theirAt, Dst: at, Size: units, Aux: auxAt, Guard: guard, Op: tableFixedText, Arg: arg, Meta: d.Meta})
	default:
		e := TableFixedEntry{Src: theirAt, Dst: at, Guard: guard, Arg: arg}
		if te.Size == me.Size {
			e.Size = me.Size
			e.Op = tableFixedCopy
			if me.Kind == 1 {
				e.Op = tableFixedBool
			}
			tableFixedPush(c, e)
		} else if te.Size < me.Size && me.Size <= 8 {
			e.Size = te.Size
			e.DstSize = uint8(me.Size)
			e.Op = tableFixedWiden
			tableFixedPush(c, e)
		} else if c.report != nil {
			c.report.KindMismatch++
		}
	}
}

func tableFixedCompile(theirs tableFixedLayoutView, myLayout []byte, dst []TableFixedDst, plan []TableFixedEntry, report *TableReport) int32 {
	if len(plan) == 0 {
		return -1
	}
	// THE READER'S OWN LAYOUT, and a failure to parse it owes its OWN name and
	// not plan_too_large: -2 is that, -1 is the plan storage (reference fix 3).
	mine, why := tableFixedParseLayout(myLayout)
	if why != "" {
		return -2
	}
	// THE WRITER'S RECORD IS THE BOUND ON EVERY ENTRY (§5.2): the root's
	// declared size, taken from the layout this plan is compiled against.
	c := tableFixedCompiler{plan: plan, capacity: int32(len(plan)), report: report,
		record: tableFixedEntryAt(theirs, 0).Size}
	tableFixedMatchChildren(&c, theirs, 0, 0, mine, 0, dst, 0, tableFixedNoGuard, 0, true)
	// ONE ENTRY PAST THE WRITER'S RECORD REFUSES THE PLAN WHOLE, by its own
	// name: -3 is layout_record_too_large, -2 the reader's own layout, -1 the
	// plan storage.
	if c.tooLarge {
		return -3
	}
	if c.overflow {
		return -1
	}
	out := int32(0)
	for i := int32(0); i < c.count; i++ {
		if out > 0 && plan[out-1].Op == plan[i].Op && tableFixedRuns(plan[i].Op) &&
			plan[out-1].Guard == plan[i].Guard && plan[out-1].Arg == plan[i].Arg &&
			plan[out-1].ArgW == plan[i].ArgW && plan[out-1].Meta == plan[i].Meta &&
			plan[out-1].Src+plan[out-1].Size == plan[i].Src &&
			plan[out-1].Dst+plan[out-1].Size == plan[i].Dst {
			plan[out-1].Size += plan[i].Size
			continue
		}
		plan[out] = plan[i]
		out++
	}
	// THE PARTITION, same as the identity builder above: the walk pushes
	// guarded and unguarded entries in field order, and a field past a union
	// would land behind a guarded one. §5.9 item 42 owes the order on this
	// path too, and the lineage plans below are compiled here, so they are
	// partitioned by construction. The returned count's plan states its split
	// at the first guarded index (mas-bandwidth/schema docs/FIXED-FORM-ALGORITHM.md §4.1), which
	// tableFixedRun derives once (§4.4).
	tableFixedPartition(plan, out)
	return out
}

// tableFixedHole is one dst range the winning plan does not land. Load copies
// declared defaults into exactly these, from one Reset image. Identity's list
// on Go is ABI padding and unselected union arms.
type tableFixedHole struct {
	Off, Size uint32
}

func tableFixedLand(cover []byte, off, n uint32) {
	if n == 0 {
		return
	}
	end := uint32(len(cover))
	if off >= end {
		return
	}
	last := off + n
	if last > end {
		last = end
	}
	for i := off; i < last; i++ {
		cover[i] = 1
	}
}

// tableFixedHoles is the complement of the unguarded dest writes. Guarded
// entries (union arms, compiled tag consts) are not always written, so they
// stay holes and keep the defaults. The write sizes match tableFixedRun.
func tableFixedHoles(plan []TableFixedEntry, count int32, dstSize uint32) []tableFixedHole {
	if dstSize == 0 {
		return nil
	}
	cover := make([]byte, dstSize)
	for i := int32(0); i < count; i++ {
		p := plan[i]
		if p.Guard != tableFixedNoGuard {
			continue
		}
		switch p.Op {
		case tableFixedCopy, tableFixedBool, tableFixedTag, tableFixedConst:
			tableFixedLand(cover, p.Dst, p.Size)
		case tableFixedCount:
			tableFixedLand(cover, p.Dst, 4)
		case tableFixedText:
			tableFixedLand(cover, p.Dst, 4)
			tableFixedLand(cover, p.Aux, p.Size)
		case tableFixedWiden:
			tableFixedLand(cover, p.Dst, uint32(p.DstSize))
		case tableFixedWidenF:
			tableFixedLand(cover, p.Dst, 8)
		case tableFixedOrdinal:
			n := uint32(4)
			if p.DstSize == 1 || p.DstSize == 2 || p.DstSize == 8 {
				n = uint32(p.DstSize)
			}
			tableFixedLand(cover, p.Dst, n)
		}
	}
	var holes []tableFixedHole
	i := uint32(0)
	for i < dstSize {
		if cover[i] != 0 {
			i++
			continue
		}
		j := i + 1
		for j < dstSize && cover[j] == 0 {
			j++
		}
		holes = append(holes, tableFixedHole{Off: i, Size: j - i})
		i = j
	}
	return holes
}

// ---- THE LINEAGE, AS STATIC DATA (mas-bandwidth/schema docs/FIXED-FORM-ALGORITHM.md §5) ----------
//
// A fixed table reads BACKWARD and never forward. A file is matched on the
// eight bytes of its header's hash against the lineage the BUILD laid down, and
// the layout it carries is held to a BYTE COMPARISON against the bytes the lock
// recorded — never walked. A hash the lineage does not hold is layout_newer
// (ship the reader); a hash it holds below the floor is layout_unsupported
// (upgrade the client). Those are the operator's two distinct answers.

// TableFixedKnownLayout is one locked layout: the wire hash a file is matched
// on, the layout bytes verbatim with its byte length BESIDE the pointer, and
// the RECORD SIZE taken from the lock and never from the file. The members are
// §5.9 #19's: hash, layout, layout_bytes, record_bytes, in that order.
type TableFixedKnownLayout struct {
	Hash        uint64
	Layout      []byte
	LayoutBytes int
	Record      int64
}

// tableFixedLineagePlan is one older entry's plan, laid down once from the
// LOCK'S bytes. Unknown and KindMismatch are the COMPILE census: a writer field
// no reader field names is counted ONCE PER PEER and never per record (§5.4).
type tableFixedLineagePlan struct {
	Entries      []TableFixedEntry
	Count        int32
	Unknown      int32
	KindMismatch int32
	Why          string
}

func tableFixedSelect(known []TableFixedKnownLayout, hash uint64) int32 {
	for i := range known {
		if known[i].Hash == hash {
			return int32(i)
		}
	}
	return -1
}

// tableFixedRefuseHash is the two refusals that report the FILE'S hash and
// nothing else (§5.3).
func tableFixedRefuseHash(report *TableReport, reason string, hash uint64) int64 {
	report.LayoutHash = hash
	return tableFixedRefuse(report, reason)
}

// tableFixedLineagePlans compiles one plan per lineage entry from THE LOCK'S
// layout bytes, at package initialization — nothing compiles on the load path,
// and there is no cache to miss (§5.2, §5.8 row 3). The identity entry keeps a
// nil plan: the baked one answers it.
func tableFixedLineagePlans(known []TableFixedKnownLayout, myLayout []byte, dst []TableFixedDst, own uint64) []tableFixedLineagePlan {
	out := make([]tableFixedLineagePlan, len(known))
	for i := range known {
		if known[i].Hash == own {
			continue
		}
		parsed, why := tableFixedParseLayout(known[i].Layout)
		if why != "" {
			// A lineage entry that is not a layout is a bug in the LOCK, not a
			// wire event; the reader still owes a name rather than a panic.
			out[i].Why = "layout_malformed"
			continue
		}
		for room := 256; ; room *= 4 {
			plan := make([]TableFixedEntry, room)
			var census TableReport
			made := tableFixedCompile(parsed, myLayout, dst, plan, &census)
			if made == -2 {
				out[i].Why = "layout_malformed"
				break
			}
			if made == -3 {
				out[i].Why = "layout_record_too_large"
				break
			}
			if made < 0 {
				if room >= 1<<18 {
					out[i].Why = "plan_too_large"
					break
				}
				continue
			}
			out[i] = tableFixedLineagePlan{
				Entries:      plan[:made],
				Count:        made,
				Unknown:      census.Unknown,
				KindMismatch: census.KindMismatch,
			}
			break
		}
	}
	return out
}

// A REFUSAL BY NAME HAS COUNTERS ALL ZERO (§5.3's joint table). A no_layout
// found mid-batch must not carry record 0's counters out with it, and a report
// a caller reuses must not keep a refusal that is no longer true. The FILE'S
// hash survives, because the two refusals that report it set it first.
func tableFixedRefuse(report *TableReport, reason string) int64 {
	hash := report.LayoutHash
	*report = TableReport{}
	report.LayoutHash = hash
	report.Verdict = TableOpenRefused
	report.Reason = reason
	return -1
}

func tableFixedOverlay(ptr unsafe.Pointer, n uintptr) []byte {
	return unsafe.Slice((*byte)(ptr), n)
}

const tableCookBuildVersion uint64 = 0x050f48c7928a3ff8

// TableByteOrder selects the target order, independently of the writing host.
type TableByteOrder uint8

const (
	TableByteOrderLittle TableByteOrder = 1
	TableByteOrderBig    TableByteOrder = 2
)

type tableCookWriter struct {
	numbering *TableNumbering
	buffer    []byte
	order     TableByteOrder
	at        int64
}

func (w *tableCookWriter) put(at int64, value uint64, width uint32) {
	if w.buffer == nil {
		return
	}
	for i := uint32(0); i < width; i++ {
		shift := i
		if w.order == TableByteOrderBig {
			shift = width - 1 - i
		}
		w.buffer[at+int64(i)] = byte(value >> (shift * 8))
	}
}
func (w *tableCookWriter) header(data, nodes, align int64) {
	w.put(0, 0x4b4f4f434d484353, 8)
	w.put(8, tableCookBuildVersion, 8)
	w.put(16, uint64(w.order), 8)
	w.put(24, uint64(data), 8)
	w.put(32, uint64(nodes)*16, 8)
	w.put(40, uint64(align), 8)
}
func (w *tableCookWriter) record(p unsafe.Pointer, t *TableTypeInfo, at int64, live bool) bool {
	for i := range t.Fields {
		f := &t.Fields[i]
		rides := live && tableJsonGuardHolds(p, t, f.Guard)
		if f.Optional {
			rides = rides && *(*bool)(unsafe.Add(p, f.PresentOffset))
		}
		if !w.field(p, f, at, rides) {
			return false
		}
	}
	return true
}
func (w *tableCookWriter) field(base unsafe.Pointer, f *TableFieldInfo, at int64, live bool) bool {
	p := unsafe.Add(base, f.Offset)
	dest := at + int64(f.CookOffset)
	if f.Optional {
		v := uint64(0)
		if *(*bool)(unsafe.Add(base, f.PresentOffset)) {
			v = 1
		}
		w.put(at+int64(f.CookPresentOffset), v, 1)
	}
	if f.List || f.Map {
		return w.container(p, f, dest, live)
	}
	count := int32(1)
	used := int32(1)
	if f.Counted {
		used = *(*int32)(unsafe.Add(base, f.CountOffset))
		if used < 0 || used > f.ArrayBound {
			return false
		}
		w.put(at+int64(f.CookCountOffset), uint64(used), 4)
	}
	if !f.Pointer && (f.TypeName == "string" || f.TypeName == "bytes" || f.TypeName == "wstring") {
		width := f.CookElemSize
		for i := int32(0); i < used; i++ {
			v := tableJsonGetRaw(unsafe.Add(p, int64(i)*int64(width)), width)
			w.put(dest+int64(i)*int64(width), v, width)
		}
		return true
	}
	if f.IsArray {
		count = f.ArrayBound
		if !f.Counted {
			used = count
		}
	}
	for i := int32(0); i < count; i++ {
		if !w.value(unsafe.Add(p, int64(i)*int64(f.ElemSize)), f, dest+int64(i)*int64(f.CookElemSize), live && i < used) {
			return false
		}
	}
	return true
}
func (w *tableCookWriter) value(p unsafe.Pointer, f *TableFieldInfo, at int64, live bool) bool {
	if f.Pointer {
		return w.reference((*int64)(p), at)
	}
	if f.Arms != nil {
		u := f.Arms()
		tag := tableJsonGetRaw(unsafe.Add(p, u.TagOffset), u.TagSize)
		if tag >= uint64(len(u.Arms)) {
			return false
		}
		w.put(at, tag, u.CookTagSize)
		if tag == 0 || u.Arms[tag].Void {
			return true
		}
		return w.field(p, &u.Arms[tag].Field, at, live)
	}
	if f.Table != nil {
		return w.record(p, f.Table(), at, live)
	}
	width := f.CookElemSize
	if width == 16 {
		lo := *(*uint64)(p)
		hi := *(*uint64)(unsafe.Add(p, 8))
		if w.order == TableByteOrderBig {
			lo, hi = hi, lo
		}
		w.put(at, lo, 8)
		w.put(at+8, hi, 8)
		return true
	}
	value := tableJsonGetRaw(p, f.ElemSize)
	if f.Kind == 1 {
		value = 0
		if *(*bool)(p) {
			value = 1
		}
	}
	w.put(at, value, width)
	return true
}
func tableCookFixed(p unsafe.Pointer, t *TableTypeInfo, buffer []byte, order TableByteOrder) bool {
	if p == nil || order != TableByteOrderLittle && order != TableByteOrderBig {
		return false
	}
	align := max(int64(8), int64(t.CookAlign))
	data := (int64(t.CookSize) + align - 1) & -align
	total := 64 + data + 16
	if int64(len(buffer)) < total {
		return false
	}
	w := tableCookWriter{order: order}
	if !w.record(p, t, 64, true) {
		return false
	}
	clear(buffer[:total])
	w.buffer = buffer
	w.header(data, 1, align)
	if !w.record(p, t, 64, true) {
		return false
	}
	w.put(64+data, 0, 8)
	w.put(64+data+8, t.Id, 8)
	return true
}

func (w *tableCookWriter) reference(slot *int64, at int64) bool {
	if *slot == 0 {
		return true
	}
	if w.numbering == nil {
		return false
	}
	i, ok := w.numbering.Index(slot)
	if !ok {
		return false
	}
	w.put(at, uint64(64+w.numbering.entries[i-1].offset-at), 8)
	return true
}
func tableCookRegion(p unsafe.Pointer, t *TableTypeInfo, buffer []byte, order TableByteOrder, measure bool, a *TableArena, allocator ...TableAllocator) int64 {
	size, _ := tableCookRegionReason(p, t, buffer, order, measure, a, allocator...)
	return size
}
func tableCookRegionReason(p unsafe.Pointer, t *TableTypeInfo, buffer []byte, order TableByteOrder, measure bool, a *TableArena, allocator ...TableAllocator) (int64, TableRefuseReason) {
	if order != TableByteOrderLittle && order != TableByteOrderBig {
		return -1, TableRefuseInvalidValue
	}
	n, ok := tableNumber(p, t, a, allocator...)
	if !ok {
		return -1, n.reason
	}
	defer n.Release()
	w := tableCookWriter{order: order, numbering: &n}
	data, align := int64(0), int64(8)
	for i := range n.entries {
		e := &n.entries[i]
		size, alignment := int64(0), int64(8)
		if e.info != nil {
			size = int64(e.info.CookSize)
			alignment = int64(e.info.CookAlign)
		} else {
			length := uint64(*(*uint32)(e.node))
			size = 8 + int64(length)
			if e.id == tableStringTypeId {
				size++
			}
		}
		align = max(align, alignment)
		data = (data + alignment - 1) & -alignment
		e.offset = data
		w.at = 64 + data + size
		if e.info != nil && !w.record(e.node, e.info, 64+data, true) {
			return -1, TableRefuseInvalidValue
		}
		data = w.at - 64
	}
	data = (data + align - 1) & -align
	total := 64 + data + int64(len(n.entries))*16
	if measure {
		return total, TableRefuseOk
	}
	if int64(len(buffer)) < total {
		return -1, TableRefuseInvalidValue
	}
	clear(buffer[:total])
	w.buffer = buffer
	w.header(data, int64(len(n.entries)), align)
	for i := range n.entries {
		e := &n.entries[i]
		at := 64 + e.offset
		if e.info != nil {
			w.at = at + int64(e.info.CookSize)
			if !w.record(e.node, e.info, at, true) {
				return -1, TableRefuseInvalidValue
			}
		} else {
			length := uint64(*(*uint32)(e.node))
			w.put(at, length, 4)
			copy(buffer[at+8:at+8+int64(length)], unsafe.Slice((*byte)(unsafe.Add(e.node, 8)), int(length)))
		}
		w.put(64+data+int64(i)*16, uint64(e.offset), 8)
		w.put(64+data+int64(i)*16+8, e.id, 8)
	}
	return total, TableRefuseOk
}
func (w *tableCookWriter) container(p unsafe.Pointer, f *TableFieldInfo, at int64, live bool) bool {
	return false
}

const tableRegionAlign int64 = 8
const tableBytesTypeId uint64 = 0x2f2ec0474f1c4fe4
const tableStringTypeId uint64 = 0x704be0d8faaffc58

// TableAllocator owns authoring and temporary writer storage. Both callbacks
// are required together; an empty pair uses Go-owned storage. Alloc supplies
// zeroed bytes aligned to tableRegionAlign and may return more than requested.
// Free always receives the original slice, with its original length and base.
// Load and LoadMeasure use caller buffers and never call this pair.
type TableAllocator struct {
	Alloc func(int64) []byte
	Free  func([]byte)
}

func (a TableAllocator) valid() bool { return (a.Alloc == nil) == (a.Free == nil) }
func (a TableAllocator) alloc(n int64) []byte {
	if !a.valid() || n <= 0 || uint64(n) > uint64(^uint(0)>>1)-uint64(tableRegionAlign) {
		return nil
	}
	if a.Alloc != nil {
		b := a.Alloc(n)
		if int64(len(b)) < n || uintptr(unsafe.Pointer(&b[0]))%uintptr(tableRegionAlign) != 0 {
			a.free(b)
			return nil
		}
		return b
	}
	raw := make([]byte, n+tableRegionAlign-1)
	off := (-uintptr(unsafe.Pointer(&raw[0]))) & uintptr(tableRegionAlign-1)
	return raw[off : off+uintptr(n)]
}
func (a TableAllocator) free(b []byte) {
	if a.Free != nil && b != nil {
		a.Free(b)
	}
}

// TableWriteContext selects allocation independently from reference addressing.
// Pass a TableAllocator for a loaded/locked region, or *TableArena for authoring
// references and that arena's allocation pair. Omit it for Go-owned temporaries.
type TableWriteContext interface {
	tableWriteOptions() (*TableArena, TableAllocator)
}

func (a TableAllocator) tableWriteOptions() (*TableArena, TableAllocator) { return nil, a }
func (a *TableArena) tableWriteOptions() (*TableArena, TableAllocator) {
	if a == nil {
		return nil, TableAllocator{}
	}
	return a, a.Allocator
}
func tableWriteOptions(options []TableWriteContext) (*TableArena, TableAllocator) {
	if len(options) > 0 && options[0] != nil {
		return options[0].tableWriteOptions()
	}
	return nil, TableAllocator{}
}

type TableRef = int64

const tableArenaSegmentBytes int64 = 1 << 20
const tableArenaSlabBytes int64 = 1 << 16
const tableArenaSegments = 4096

type tableArenaSegment struct {
	data  []byte
	owned bool
}
type TableArena struct {
	Allocator   TableAllocator
	Locked      bool
	next        atomic.Uint64
	segments    [tableArenaSegments]atomic.Pointer[tableArenaSegment]
	storage     [tableArenaSegments]tableArenaSegment
	initialized bool
	mutex       sync.Mutex
}

func (a *TableArena) Init(allocator ...TableAllocator) bool {
	if a == nil || a.initialized {
		return false
	}
	pair := TableAllocator{}
	if len(allocator) > 0 {
		pair = allocator[0]
	}
	if !pair.valid() {
		return false
	}
	a.Allocator = pair
	a.Locked = false
	a.initialized = true
	a.next.Store(uint64(tableArenaSlabBytes))
	return true
}
func (a *TableArena) Shutdown() {
	for i := range a.segments {
		if s := a.segments[i].Swap(nil); s != nil {
			if s.owned {
				a.Allocator.free(s.data)
			}
			*s = tableArenaSegment{}
		}
	}
	a.initialized = false
	a.next.Store(0)
}
func (a *TableArena) At(ref TableRef) unsafe.Pointer {
	if ref <= 0 || ref >= tableArenaSegmentBytes*tableArenaSegments {
		return nil
	}
	s := a.segments[ref/tableArenaSegmentBytes].Load()
	if s == nil {
		return nil
	}
	return unsafe.Pointer(&s.data[ref%tableArenaSegmentBytes])
}
func (a *TableArena) grab(bytes int64) (int64, int64) {
	if !a.initialized || a.Locked || bytes <= 0 {
		return 0, 0
	}
	span := bytes > tableArenaSlabBytes
	size := tableArenaSlabBytes
	if span {
		size = (bytes + tableArenaSegmentBytes - 1) & -tableArenaSegmentBytes
	}
	var at, end uint64
	for {
		at = a.next.Load()
		if at == 0 {
			return 0, 0
		}
		if span {
			at = (at + uint64(tableArenaSegmentBytes) - 1) & ^uint64(tableArenaSegmentBytes-1)
		}
		end = at + uint64(size)
		if end > uint64(tableArenaSegmentBytes*tableArenaSegments) {
			return 0, 0
		}
		old := a.next.Load()
		candidate := old
		if span {
			candidate = (old + uint64(tableArenaSegmentBytes) - 1) & ^uint64(tableArenaSegmentBytes-1)
		}
		if candidate != at {
			continue
		}
		if a.next.CompareAndSwap(old, end) {
			break
		}
	}
	first, last := int64(at)/tableArenaSegmentBytes, (int64(end)-1)/tableArenaSegmentBytes
	if a.segments[first].Load() == nil {
		a.mutex.Lock()
		if a.segments[first].Load() == nil {
			n := (last - first + 1) * tableArenaSegmentBytes
			data := a.Allocator.alloc(n)
			if data == nil {
				a.mutex.Unlock()
				return 0, 0
			}
			clear(data)
			for i := first; i <= last; i++ {
				a.storage[i] = tableArenaSegment{data: data[(i-first)*tableArenaSegmentBytes:], owned: i == first}
				a.segments[i].Store(&a.storage[i])
			}
		}
		a.mutex.Unlock()
	}
	return int64(at), int64(end)
}

type TableWorker struct {
	Arena      *TableArena
	front, end int64
	refused    bool
}

func (w *TableWorker) Alloc(n int64) (unsafe.Pointer, TableRef) {
	if w == nil || w.Arena == nil || w.Arena.Locked || n <= 0 {
		return nil, 0
	}
	n = tableRegionRound(n)
	if n > tableArenaSlabBytes {
		at, _ := w.Arena.grab(n)
		return w.Arena.At(at), at
	}
	if w.front+n > w.end {
		w.front, w.end = w.Arena.grab(n)
		if w.front == 0 {
			return nil, 0
		}
	}
	at := w.front
	w.front += n
	return w.Arena.At(at), at
}
func tableOptionalArena(a []*TableArena) *TableArena {
	if len(a) > 0 {
		return a[0]
	}
	return nil
}
func tableRefAt(slot *TableRef, a *TableArena) unsafe.Pointer {
	if slot == nil || *slot == 0 {
		return nil
	}
	if a != nil {
		return a.At(*slot)
	}
	return unsafe.Add(unsafe.Pointer(slot), *slot)
}
func tableRegionCount(base unsafe.Pointer, f *TableFieldInfo) int32 {
	if f.Counted {
		return *(*int32)(unsafe.Add(base, f.CountOffset))
	}
	return f.ArrayBound
}
func tableRegionRound(n int64) int64 { return (n + tableRegionAlign - 1) & -tableRegionAlign }

type tableNodeEntry struct {
	json   tableJsonGraphNode
	node   unsafe.Pointer
	info   *TableTypeInfo
	id     uint64
	open   bool
	offset int64
}

// The root and arena keep the source storage live while pointer-free backing
// allocations hold the index and entries. Temporary storage is released by caller.
type TableNumbering struct {
	reason              TableRefuseReason
	arena               *TableArena
	root                unsafe.Pointer
	allocator           TableAllocator
	entries             []tableNodeEntry
	buckets             []uint64
	memory, indexMemory []byte
}

func (n *TableNumbering) Release() {
	n.allocator.free(n.memory)
	n.allocator.free(n.indexMemory)
	n.memory = nil
	n.indexMemory = nil
	n.entries = nil
	n.buckets = nil
	n.root = nil
}
func (n *TableNumbering) find(p unsafe.Pointer) (int, bool) {
	if p == nil || len(n.buckets) == 0 {
		return 0, false
	}
	h := uint64(uintptr(p))
	h ^= h >> 33
	h *= 0xff51afd7ed558ccd
	h ^= h >> 33
	mask := uint64(len(n.buckets) - 1)
	for slot := h & mask; ; slot = (slot + 1) & mask {
		v := n.buckets[slot]
		if v == 0 {
			return int(slot), false
		}
		if n.entries[v-1].node == p {
			return int(v - 1), true
		}
	}
}
func (n *TableNumbering) grow() bool {
	capacity := cap(n.entries) * 2
	if capacity < 16 {
		capacity = 16
	}
	if capacity > int(^uint(0)>>1)/int(unsafe.Sizeof(tableNodeEntry{})) {
		return false
	}
	memory := n.allocator.alloc(int64(capacity) * int64(unsafe.Sizeof(tableNodeEntry{})))
	if memory == nil {
		return false
	}
	index := n.allocator.alloc(int64(capacity) * 16)
	if index == nil {
		n.allocator.free(memory)
		return false
	}
	clear(index)
	entries := unsafe.Slice((*tableNodeEntry)(unsafe.Pointer(&memory[0])), capacity)
	copy(entries, n.entries)
	length := len(n.entries)
	oldMemory, oldIndex := n.memory, n.indexMemory
	n.memory, n.indexMemory = memory, index
	n.entries = entries[:length]
	n.buckets = unsafe.Slice((*uint64)(unsafe.Pointer(&index[0])), capacity*2)
	for i := range n.entries {
		slot, _ := n.find(n.entries[i].node)
		n.buckets[slot] = uint64(i + 1)
	}
	n.allocator.free(oldMemory)
	n.allocator.free(oldIndex)
	return true
}
func (n *TableNumbering) Index(slot *TableRef) (uint64, bool) {
	if n == nil {
		return 0, false
	}
	i, ok := n.find(tableRefAt(slot, n.arena))
	return uint64(i + 1), ok
}
func (n *TableNumbering) visit(p unsafe.Pointer, t *TableTypeInfo, id uint64) bool {
	if p == nil {
		return true
	}
	if i, ok := n.find(p); ok {
		if n.entries[i].open {
			n.reason = TableRefuseDataCycle
			return false
		}
		if n.entries[i].id != id {
			n.reason = TableRefuseInvalidValue
			return false
		}
		return true
	}
	if len(n.entries) == cap(n.entries) && !n.grow() {
		n.reason = TableRefuseAllocationFailed
		return false
	}
	slot, _ := n.find(p)
	i := len(n.entries)
	n.entries = n.entries[:i+1]
	n.entries[i] = tableNodeEntry{node: p, info: t, id: id, open: true}
	n.buckets[slot] = uint64(i + 1)
	a := n.arena
	if t != nil && !tableRegionEdges(p, t, func(slot *TableRef, f *TableFieldInfo) bool {
		var target *TableTypeInfo
		if f.Table != nil {
			target = f.Table()
		}
		return n.visit(tableRefAt(slot, a), target, f.TargetId)
	}) {
		return false
	}
	n.entries[i].open = false
	return true
}
func tableNumber(root unsafe.Pointer, info *TableTypeInfo, a *TableArena, allocator ...TableAllocator) (TableNumbering, bool) {
	n := TableNumbering{arena: a, root: root}
	if a != nil {
		n.allocator = a.Allocator
	}
	if len(allocator) > 0 {
		n.allocator = allocator[0]
	}
	if root == nil || !n.visit(root, info, info.Id) {
		if n.reason == TableRefuseOk {
			n.reason = TableRefuseInvalidValue
		}
		n.Release()
		return n, false
	}
	return n, true
}
func tableRegionEdges(base unsafe.Pointer, info *TableTypeInfo, visit func(*TableRef, *TableFieldInfo) bool) bool {
	for i := range info.Fields {
		f := &info.Fields[i]
		if !tableJsonGuardHolds(base, info, f.Guard) || f.Optional && !*(*bool)(unsafe.Add(base, f.PresentOffset)) {
			continue
		}
		p := unsafe.Add(base, f.Offset)
		count := int32(1)
		if f.IsArray {
			count = tableRegionCount(base, f)
			if count < 0 || count > f.ArrayBound {
				return false
			}
		}
		for j := int32(0); j < count; j++ {
			at := unsafe.Add(p, uintptr(j)*uintptr(f.ElemSize))
			if !tableRegionValueEdges(at, f, visit) {
				return false
			}
		}
	}
	return true
}
func tableRegionValueEdges(p unsafe.Pointer, f *TableFieldInfo, visit func(*TableRef, *TableFieldInfo) bool) bool {
	if f.Pointer {
		return visit((*TableRef)(p), f)
	}
	if f.Kind == 13 && f.Table != nil {
		return tableRegionEdges(p, f.Table(), visit)
	}
	if f.Kind == 15 && f.Arms != nil {
		arms := f.Arms()
		tag := tableJsonGetRaw(unsafe.Add(p, arms.TagOffset), arms.TagSize)
		if tag >= uint64(len(arms.Arms)) {
			return false
		}
		if tag != 0 {
			arm := &arms.Arms[tag]
			if arm.Void {
				return true
			}
			af := &arm.Field
			at := unsafe.Add(p, af.Offset)
			count := int32(1)
			if af.IsArray {
				count = tableRegionCount(p, af)
				if count < 0 || count > af.ArrayBound {
					return false
				}
			}
			for j := int32(0); j < count; j++ {
				if !tableRegionValueEdges(unsafe.Add(at, uintptr(j)*uintptr(af.ElemSize)), af, visit) {
					return false
				}
			}
		}
	}
	return true
}
func tableNodeWrite(w *TableWriter, e *tableNodeEntry) bool {
	if e.info != nil {
		return e.info.SaveBody(w, e.node)
	}
	length := uint64(*(*uint32)(e.node))
	w.Raw(unsafe.Slice((*byte)(unsafe.Add(e.node, 8)), int(length)))
	return !w.Overflow
}
func tableNodeMeasure(w *TableWriter, ids *TableIds, e *tableNodeEntry) int64 {
	*w = TableWriter{Measuring: true, Ids: ids}
	if !tableNodeWrite(w, e) {
		return -1
	}
	return w.Offset
}

// A typed frame keeps its pointers visible to Go's collector. The descriptor
// callbacks make it escape once per call; node-proportional storage uses the pair.
type tableWireFrame struct {
	numbering       TableNumbering
	ids             TableIds
	writer, measure TableWriter
}

func tableRegionSave(root unsafe.Pointer, info *TableTypeInfo, buffer []byte, measure bool, a *TableArena, allocator ...TableAllocator) int64 {
	n, _ := tableRegionSaveReason(root, info, buffer, measure, a, allocator...)
	return n
}
func tableRegionSaveReason(root unsafe.Pointer, info *TableTypeInfo, buffer []byte, measure bool, a *TableArena, allocator ...TableAllocator) (int64, TableRefuseReason) {
	frame := tableWireFrame{}
	var ok bool
	frame.numbering, ok = tableNumber(root, info, a, allocator...)
	if !ok {
		return -1, frame.numbering.reason
	}
	n := &frame.numbering
	defer n.Release()
	ids := &frame.ids
	*ids = TableIds{Numbering: n}
	w := &frame.writer
	*w = TableWriter{Buffer: buffer, Measuring: measure, Ids: ids}
	w.Put8(1)
	if !info.SaveBody(w, root) {
		return -1, TableRefuseInvalidValue
	}
	w.Offset--
	if len(n.entries) > 1 {
		w.Id(0xffffffffffffffff)
		w.Put8(12)
		payload := tableLebBytes(uint64(len(n.entries) - 1))
		for i := 1; i < len(n.entries); i++ {
			e := &n.entries[i]
			payload += tableLebBytes(ids.Ref(e.id))
			size := tableNodeMeasure(&frame.measure, ids, e)
			if size < 0 {
				return -1, TableRefuseInvalidValue
			}
			payload += tableLebBytes(uint64(size)) + size
		}
		w.PutLeb(uint64(payload))
		w.PutLeb(uint64(len(n.entries) - 1))
		for i := 1; i < len(n.entries); i++ {
			e := &n.entries[i]
			w.Id(e.id)
			size := tableNodeMeasure(&frame.measure, ids, e)
			if size < 0 {
				return -1, TableRefuseInvalidValue
			}
			w.PutLeb(uint64(size))
			if w.Measuring {
				w.Advance(size)
			} else if !tableNodeWrite(w, e) {
				return -1, TableRefuseInvalidValue
			}
		}
	}
	w.Put8(0)
	w.Trailer()
	if w.Overflow || ids.Overflow {
		return -1, TableRefuseInvalidValue
	}
	return w.Offset, TableRefuseOk
}

type TableNodeDirEntry struct{ Offset, TypeId uint64 }
type TableNodeMap struct {
	Base    unsafe.Pointer
	Entries []TableNodeDirEntry
	Good    bool
	Arena   bool
}

func (m TableNodeMap) Resolve(slot *TableRef, index, target uint64, r *TableReport) {
	*slot = 0
	if index == 0 || !m.Good {
		return
	}
	if index > uint64(len(m.Entries)) {
		r.Malformed = true
		return
	}
	entry := m.Entries[index-1]
	if entry.Offset == ^uint64(0) {
		return
	}
	if entry.TypeId != target {
		r.KindMismatch++
		return
	}
	if m.Arena {
		*slot = int64(entry.Offset)
	} else {
		*slot = int64(uintptr(unsafe.Add(m.Base, entry.Offset)) - uintptr(unsafe.Pointer(slot)))
	}
}

type tableNodeScan struct {
	payload           TableReader
	declared, records uint64
	present, bad      bool
}

func tableNodeScanBegin(r TableReader) tableNodeScan {
	s := tableNodeScan{}
	r.Offset = 0
	for {
		ref, ok := r.Leb()
		if !ok || ref == 0 {
			break
		}
		id, ok := r.Resolve(ref)
		if !ok || !r.Has(1) {
			break
		}
		kind := r.Get8()
		if id == 0xffffffffffffffff {
			s.present = true
			if kind != 12 {
				s.bad = true
				return s
			}
			sub, ok := r.Body()
			if !ok {
				s.bad = true
				return s
			}
			s.payload = sub
		} else if !r.Skip(kind) {
			break
		}
	}
	if s.present {
		var ok bool
		s.declared, ok = s.payload.Leb()
		if !ok {
			s.bad = true
		}
	}
	return s
}
func (s *tableNodeScan) next() (uint64, TableReader, bool) {
	r := &s.payload
	if s.bad || r.Offset >= int64(len(r.Buffer)) {
		return 0, TableReader{}, false
	}
	ref, ok := r.Leb()
	if !ok {
		s.bad = true
		return 0, TableReader{}, false
	}
	id, ok := r.Resolve(ref)
	if !ok {
		s.bad = true
		return 0, TableReader{}, false
	}
	body, ok := r.Body()
	if !ok {
		s.bad = true
		return 0, TableReader{}, false
	}
	s.records++
	return id, body, true
}
func (s *tableNodeScan) whole() bool { return !s.bad && (!s.present || s.declared == s.records) }
func tableNodeStorage(id uint64, body TableReader, nodeType func(uint64) *TableTypeInfo, blobs int) int64 {
	n, _ := tableNodeStorageReason(id, body, nodeType, blobs)
	return n
}
func tableNodeStorageReason(id uint64, body TableReader, nodeType func(uint64) *TableTypeInfo, blobs int) (int64, TableRefuseReason) {
	if t := nodeType(id); t != nil {
		return tableRegionRound(int64(t.Size)), TableRefuseOk
	}
	if id == tableBytesTypeId && blobs&1 != 0 || id == tableStringTypeId && blobs&2 != 0 {
		extra := int64(0)
		if id == tableStringTypeId {
			extra = 1
		}
		if int64(len(body.Buffer)) > 0xffffffff {
			return -2, TableRefuseBlobOverSizeCap
		}
		return tableRegionRound(8 + int64(len(body.Buffer)) + extra), TableRefuseOk
	}
	return -1, TableRefuseOk
}
func tableRegionMeasure(wire []byte, root *TableTypeInfo, nodeType func(uint64) *TableTypeInfo, blobs int) (int64, int64, TableOpenVerdict) {
	n, a, v, _ := tableRegionMeasureReason(wire, root, nodeType, blobs)
	return n, a, v
}
func tableRegionMeasureReason(wire []byte, root *TableTypeInfo, nodeType func(uint64) *TableTypeInfo, blobs int) (int64, int64, TableOpenVerdict, TableRefuseReason) {
	var ignored TableReport
	r, verdict := tableOpenFramed(wire, &ignored)
	if verdict != TableOpenOk {
		reason := TableRefuseWireDamaged
		if verdict == TableOpenRefused {
			reason = TableRefuseUnknownForm
		}
		return -1, 0, verdict, reason
	}
	data := tableRegionRound(int64(root.Size))
	s := tableNodeScanBegin(r)
	for {
		id, body, ok := s.next()
		if !ok {
			break
		}
		n, reason := tableNodeStorageReason(id, body, nodeType, blobs)
		if n == -2 {
			return -1, 0, TableOpenRefused, reason
		}
		if n > 0 {
			data += n
		}
	}
	attribution := int64(s.records+1) * 16
	return data + attribution, attribution, TableOpenOk, TableRefuseOk
}

func tableRegionLoad(region, wire []byte, root *TableTypeInfo, nodeType func(uint64) *TableTypeInfo, blobs int, report *TableReport) unsafe.Pointer {
	if report == nil {
		var ignored TableReport
		report = &ignored
	}
	r, verdict := tableOpenFramed(wire, report)
	report.Verdict = verdict
	if verdict != TableOpenOk {
		if verdict == TableOpenDamaged {
			report.Malformed = true
		} else {
			report.Reason = "unsupported wire form"
		}
		return nil
	}
	n, attr, _ := tableRegionMeasure(wire, root, nodeType, blobs)
	if n < 0 || int64(len(region)) < n || len(region) == 0 || uintptr(unsafe.Pointer(&region[0]))%uintptr(tableRegionAlign) != 0 {
		report.Malformed = true
		return nil
	}
	clear(region)
	data := n - attr
	base := unsafe.Pointer(&region[0])
	directory := unsafe.Slice((*TableNodeDirEntry)(unsafe.Add(base, data)), int(attr/16))
	directory[0] = TableNodeDirEntry{0, root.Id}
	nodes := TableNodeMap{Base: base, Entries: directory}
	root.Reset(base)
	s := tableNodeScanBegin(r)
	used := tableRegionRound(int64(root.Size))
	k := 1
	unknown := int32(0)
	for {
		id, body, ok := s.next()
		if !ok {
			break
		}
		size := tableNodeStorage(id, body, nodeType, blobs)
		directory[k].TypeId = id
		if id == tableStringTypeId && blobs&2 != 0 && !tableUtf8Valid(body.Buffer) {
			directory[k].Offset = ^uint64(0)
			report.Malformed = true
		} else if size <= 0 {
			directory[k].Offset = ^uint64(0)
			unknown++
		} else {
			directory[k].Offset = uint64(used)
			p := unsafe.Add(base, used)
			if t := nodeType(id); t != nil {
				t.Reset(p)
			} else {
				*(*TableBlob)(p) = TableBlob{Length: uint32(uint64(len(body.Buffer)))}
			}
			used += size
		}
		k++
	}
	nodes.Good = s.whole()
	if nodes.Good {
		report.Unknown += unknown
	} else {
		report.Malformed = true
	}
	if nodes.Good {
		s = tableNodeScanBegin(r)
		k = 1
		for {
			id, body, ok := s.next()
			if !ok {
				break
			}
			if directory[k].Offset != ^uint64(0) {
				p := unsafe.Add(base, directory[k].Offset)
				if t := nodeType(id); t != nil {
					body.Nodes = nodes
					t.LoadBody(body, p)
				} else {
					copy(unsafe.Slice((*byte)(unsafe.Add(p, 8)), len(body.Buffer)), body.Buffer)
				}
			}
			k++
		}
	}
	r.Nodes = nodes
	r.Nested = false
	root.LoadBody(r, base)
	return base
}
func tablePackNodeBytes(e *tableNodeEntry, a *TableArena) int64 {
	if e.info != nil {
		return tableRegionRound(int64(e.info.Size))
	}
	extra := int64(0)
	if e.id == tableStringTypeId {
		extra = 1
	}
	return tableRegionRound(8 + int64(*(*uint32)(e.node)) + extra)
}
func tablePackOffsets(n *TableNumbering) int64 {
	size := int64(0)
	for i := range n.entries {
		e := &n.entries[i]
		extent := tablePackNodeBytes(e, n.arena)
		if extent < 0 || size > math.MaxInt64-extent {
			return -1
		}
		e.offset = size
		size += extent
	}
	return size
}
func tableRegionPackMeasure(root unsafe.Pointer, info *TableTypeInfo, a *TableArena) int64 {
	n, _ := tableRegionPackMeasureReason(root, info, a)
	return n
}
func tableRegionPackMeasureReason(root unsafe.Pointer, info *TableTypeInfo, a *TableArena) (int64, TableRefuseReason) {
	n, ok := tableNumber(root, info, a)
	if !ok {
		return -1, n.reason
	}
	defer n.Release()
	size := tablePackOffsets(&n)
	if size < 0 {
		return -1, TableRefuseInvalidValue
	}
	return size, TableRefuseOk
}
func tableRegionPack(root unsafe.Pointer, info *TableTypeInfo, a *TableArena) ([]byte, []byte, bool) {
	total := tableRegionPackMeasure(root, info, a)
	if total < 0 {
		return nil, nil, false
	}
	n, ok := tableNumber(root, info, a)
	if !ok {
		return nil, nil, false
	}
	defer n.Release()
	size := tablePackOffsets(&n)
	if size < 0 || size != total {
		return nil, nil, false
	}
	allocation := a.Allocator.alloc(size)
	if allocation == nil {
		return nil, nil, false
	}
	region := allocation[:size]
	clear(region)
	base := unsafe.Pointer(&region[0])
	for i := range n.entries {
		e := &n.entries[i]
		p := unsafe.Add(base, e.offset)
		if e.info == nil {
			copy(unsafe.Slice((*byte)(p), 8+int(uint64(*(*uint32)(e.node)))), unsafe.Slice((*byte)(e.node), 8+int(uint64(*(*uint32)(e.node)))))
			continue
		}
		copy(unsafe.Slice((*byte)(p), int(e.info.Size)), unsafe.Slice((*byte)(e.node), int(e.info.Size)))
		if !tableRegionEdges(p, e.info, func(slot *TableRef, f *TableFieldInfo) bool {
			if *slot == 0 {
				return true
			}
			target := a.At(*slot)
			idx, ok := n.find(target)
			if !ok {
				return false
			}
			*slot = int64(uintptr(unsafe.Add(base, n.entries[idx].offset)) - uintptr(unsafe.Pointer(slot)))
			return true
		}) {
			a.Allocator.free(allocation)
			return nil, nil, false
		}
	}
	return region, allocation, true
}

func tableRegionFromJson(value unsafe.Pointer, info *TableTypeInfo, worker *TableWorker, text []byte, report *TableReport) bool {
	if report == nil {
		var ignored TableReport
		report = &ignored
	}
	if value == nil {
		report.Malformed = true
		return false
	}
	graph := tableJsonGraph{alloc: worker.Alloc, allocate: worker.Arena.Allocator.alloc, release: worker.Arena.Allocator.free}
	defer graph.close()
	in := tableJsonIn{text: text, report: report, graph: &graph}
	info.Reset(value)
	ok := tableJsonReadTable(&in, value, info, 0)
	in.space()
	if !ok || in.bad || in.pos != len(text) {
		report.Malformed = true
		return false
	}
	return true
}
func tableRegionToJson(value unsafe.Pointer, info *TableTypeInfo, buffer []byte, allocator ...TableAllocator) int64 {
	n, ok := tableNumber(value, info, nil, allocator...)
	if !ok {
		return -1
	}
	defer n.Release()
	graph := tableJsonGraph{node: func(p unsafe.Pointer) *tableJsonGraphNode {
		i, ok := n.find(p)
		if !ok {
			return nil
		}
		return &n.entries[i].json
	}}
	for i := range n.entries {
		e := &n.entries[i]
		if e.info != nil && !tableRegionEdges(e.node, e.info, func(slot *TableRef, f *TableFieldInfo) bool {
			p := tableRefAt(slot, nil)
			if p != nil {
				graph.node(p).refs++
			}
			return true
		}) {
			return -1
		}
	}
	out := tableJsonOut{buffer: buffer, measure: buffer == nil, graph: &graph}
	if !tableJsonWriteValue(&out, value, info, 0) {
		return -1
	}
	out.put('\n')
	if out.overflow {
		return -1
	}
	return out.offset
}

// Blob ABI follows the established tool and C++ byte contract: u32 length, u32 zero.
// SPEC-TABLES §7.2 currently labels this u64; the big-endian fixtures distinguish them.
type TableBlob struct {
	Length uint32
	Zero   uint32
}

// TableBytesView borrows its backing region or arena. Keep that storage alive
// and do not free, reuse, or shut it down while using the view.
type TableBytesView struct {
	Data   []byte
	Length int64
}

// TableStringView has the same borrowed lifetime as TableBytesView.
type TableStringView struct {
	Data   []byte
	Length int64
}

func TableBlobAt(slot *TableRef, arena ...*TableArena) *TableBlob {
	return (*TableBlob)(tableRefAt(slot, tableOptionalArena(arena)))
}
func TableBytesAt(slot *TableRef, arena ...*TableArena) TableBytesView {
	p := TableBlobAt(slot, arena...)
	if p == nil {
		return TableBytesView{}
	}
	return TableBytesView{unsafe.Slice((*byte)(unsafe.Add(unsafe.Pointer(p), 8)), int(p.Length)), int64(p.Length)}
}
func TableStringAt(slot *TableRef, arena ...*TableArena) TableStringView {
	v := TableBytesAt(slot, arena...)
	return TableStringView{v.Data, v.Length}
}
func (w *TableWorker) allocBlob(length int64, terminated bool) ([]byte, TableRef) {
	if length < 0 || length > 0xffffffff {
		return nil, 0
	}
	extra := int64(0)
	if terminated {
		extra = 1
	}
	p, ref := w.Alloc(8 + length + extra)
	if p == nil {
		return nil, 0
	}
	*(*TableBlob)(p) = TableBlob{Length: uint32(uint64(length))}
	return unsafe.Slice((*byte)(unsafe.Add(p, 8)), int(length)), ref
}
func (w *TableWorker) AllocBytes(length int64) ([]byte, TableRef)  { return w.allocBlob(length, false) }
func (w *TableWorker) AllocString(length int64) ([]byte, TableRef) { return w.allocBlob(length, true) }
func TableBytesEmplace(worker *TableWorker, slot *TableRef, length int64) []byte {
	data, ref := worker.AllocBytes(length)
	*slot = ref
	return data
}
func TableStringEmplace(worker *TableWorker, slot *TableRef, text []byte) []byte {
	data, ref := worker.AllocString(int64(len(text)))
	*slot = ref
	copy(data, text)
	return data
}

func tableBuilderLoad(p unsafe.Pointer, ref TableRef, worker *TableWorker, wire []byte, root *TableTypeInfo, nodeType func(uint64) *TableTypeInfo, blobs int, report *TableReport) bool {
	if report == nil {
		var ignored TableReport
		report = &ignored
	}
	r, verdict := tableOpenFramed(wire, report)
	report.Verdict = verdict
	if verdict != TableOpenOk {
		if verdict == TableOpenDamaged {
			report.Malformed = true
		} else {
			report.Reason = "unsupported wire form"
		}
		return false
	}
	if p == nil || worker == nil || worker.Arena == nil || worker.Arena.Locked {
		report.Malformed = true
		return false
	}
	worker.refused = false
	scan := tableNodeScanBegin(r)
	for {
		_, _, ok := scan.next()
		if !ok {
			break
		}
	}
	count := int64(scan.records + 1)
	memory := worker.Arena.Allocator.alloc(count * 16)
	if memory == nil {
		report.Malformed = true
		return false
	}
	defer worker.Arena.Allocator.free(memory)
	clear(memory)
	directory := unsafe.Slice((*TableNodeDirEntry)(unsafe.Pointer(&memory[0])), int(count))
	directory[0] = TableNodeDirEntry{uint64(ref), root.Id}
	nodes := TableNodeMap{Entries: directory, Arena: true}
	scan = tableNodeScanBegin(r)
	k := 1
	unknown := int32(0)
	for {
		id, body, ok := scan.next()
		if !ok {
			break
		}
		directory[k] = TableNodeDirEntry{^uint64(0), id}
		t := nodeType(id)
		isblob := id == tableBytesTypeId && blobs&1 != 0 || id == tableStringTypeId && blobs&2 != 0
		if t == nil && !isblob {
			unknown++
			k++
			continue
		}
		if id == tableStringTypeId && !tableUtf8Valid(body.Buffer) {
			report.Malformed = true
			k++
			continue
		}
		size := int64(0)
		if t != nil {
			size = int64(t.Size)
		} else {
			if uint64(len(body.Buffer)) > math.MaxUint32 {
				return false
			}
			size = 8 + int64(len(body.Buffer))
			if id == tableStringTypeId {
				size++
			}
		}
		node, at := worker.Alloc(size)
		if node == nil {
			report.Malformed = true
			return false
		}
		directory[k].Offset = uint64(at)
		if t != nil {
			t.Reset(node)
		} else {
			*(*TableBlob)(node) = TableBlob{Length: uint32(uint64(len(body.Buffer)))}
			copy(unsafe.Slice((*byte)(unsafe.Add(node, 8)), len(body.Buffer)), body.Buffer)
		}
		k++
	}
	nodes.Good = scan.whole()
	if nodes.Good {
		report.Unknown += unknown
	} else {
		report.Malformed = true
	}
	if nodes.Good {
		scan = tableNodeScanBegin(r)
		k = 1
		for {
			id, body, ok := scan.next()
			if !ok {
				break
			}
			if directory[k].Offset != ^uint64(0) {
				if t := nodeType(id); t != nil {
					body.Nodes = nodes
					t.LoadBody(body, worker.Arena.At(int64(directory[k].Offset)))
					if worker.refused {
						return false
					}
				}
			}
			k++
		}
	}
	r.Nodes = nodes
	r.Nested = false
	ok := root.LoadBody(r, p)
	return ok && !worker.refused
}

const tableRetainPathDepth = 1

var tableRetainKnown = [...]uint64{0x01ed845cde646231, 0x032c13736048bf35, 0x08a64b07b54df8d4, 0x08b72e07b55c3ac0, 0x09313a07b5c3ab60, 0x1ea2a003ee111244, 0x2f2ec0474f1c4fe4, 0x335f27192ff5d5ed, 0x3ec4da71c1a62754, 0x41fdbf81bf00fdc1, 0x445341bdde0ebac7, 0x4a63ac6d3363201e, 0x65e8d7f3474f2639, 0x6c80030e2762459d, 0x704be0d8faaffc58, 0x90ab055b72415078, 0xae3e8213b7ddaffe, 0xc4bcadba8e631b86, 0xce57648e554861b7, 0xcedbf52a5907a034, 0xd3e5a2416925d46e, 0xe5f1ed4363ea5da1, 0xea14e391abc0c981, 0xee9dbaad45e3448d, 0xf887924470beb30a, 0xf9c5e219a019a6e2, 0xfc9697d1196e6ba6, 0xffffffffffffffff}

// TableRetain owns no storage. The caller supplies both bounded buffers; a
// whole unknown record that does not fit is dropped and counted once.
// Maximum nesting of a retained resolved payload (SPEC-TABLES §6.6).
const tableRetainWalkDepthMax = 64

type TableRetainId struct {
	Id   uint64
	Slot int
}
type TableRetain struct {
	Bytes     []byte
	Ids       []TableRetainId
	Used      int64
	Count     int
	idUsed    int
	base      unsafe.Pointer
	directory []TableNodeDirEntry
}
type tableRetainStep struct{ ordinal, index uint32 }
type tableRetainPath struct {
	at    unsafe.Pointer
	node  uint32
	depth int
	steps [tableRetainPathDepth]tableRetainStep
}

func (p tableRetainPath) step(ordinal, index uint32) tableRetainPath {
	if p.depth < len(p.steps) {
		p.steps[p.depth] = tableRetainStep{ordinal, index}
	}
	p.depth++
	return p
}
func (t *TableRetain) reset(base unsafe.Pointer, directory []TableNodeDirEntry) {
	if t != nil {
		t.Used = 0
		t.Count = 0
		t.idUsed = 0
		t.base = base
		t.directory = directory
	}
}
func tableRetainRecordSize(b []byte) int { return int(binary.LittleEndian.Uint32(b)) }
func (t *TableRetain) matches(b []byte, p tableRetainPath, under bool, field bool, ordinal uint32) bool {
	node := binary.LittleEndian.Uint32(b[4:])
	depth := int(binary.LittleEndian.Uint32(b[8:]))
	if node == 0 || int(node) > len(t.directory) || t.directory[node-1].Offset == ^uint64(0) || unsafe.Add(t.base, t.directory[node-1].Offset) != p.at {
		return false
	}
	if depth < p.depth || !under && depth != p.depth || field && depth == p.depth || p.depth > len(p.steps) {
		return false
	}
	for i := 0; i < p.depth; i++ {
		if binary.LittleEndian.Uint32(b[26+i*8:]) != p.steps[i].ordinal || binary.LittleEndian.Uint32(b[30+i*8:]) != p.steps[i].index {
			return false
		}
	}
	return !field || binary.LittleEndian.Uint32(b[26+p.depth*8:]) == ordinal
}
func (t *TableRetain) discard(p tableRetainPath, field bool, ordinal uint32) {
	if t == nil {
		return
	}
	at, out, count := 0, 0, 0
	for at < int(t.Used) {
		n := tableRetainRecordSize(t.Bytes[at:])
		b := t.Bytes[at : at+n]
		if !t.matches(b, p, true, field, ordinal) {
			copy(t.Bytes[out:], b)
			out += n
			count++
		}
		at += n
	}
	t.Used = int64(out)
	t.Count = count
}
func (t *TableRetain) clearPlaced() {
	if t == nil {
		return
	}
	for at := 0; at < int(t.Used); {
		t.Bytes[at+25] = 0
		at += tableRetainRecordSize(t.Bytes[at:])
	}
}
func (t *TableRetain) countLost(r *TableReport) {
	if t == nil || r == nil {
		return
	}
	for at := 0; at < int(t.Used); {
		if t.Bytes[at+25] == 0 {
			r.RetainLost++
		}
		at += tableRetainRecordSize(t.Bytes[at:])
	}
}

type tableRetainPlainReader = TableReader
type TableRetainReader struct {
	tableRetainPlainReader
	Retain *TableRetain
	Path   tableRetainPath
}

func (r *TableRetainReader) Body() (TableRetainReader, bool) {
	sub, ok := r.tableRetainPlainReader.Body()
	return TableRetainReader{tableRetainPlainReader: sub, Retain: r.Retain, Path: r.Path}, ok
}
func (r *TableRetainReader) capture(id uint64, kind uint8) bool {
	at := r.Offset
	if !r.Skip(kind) {
		return false
	}
	if r.Retain == nil {
		return true
	}
	t := r.Retain
	p := r.Path
	limit := int64(len(t.Bytes)) - t.Used - int64(26+p.depth*8)
	if limit < 0 {
		r.Report.RetainLost++
		return true
	}
	probe := tableRetainIn{r: TableReader{Buffer: r.Buffer[at:r.Offset], Ids: r.Ids}, w: TableWriter{Measuring: true}, limit: limit}
	if p.depth > len(p.steps) || !probe.payload(kind, 0) || probe.r.Offset != int64(len(probe.r.Buffer)) {
		r.Report.RetainLost++
		return true
	}
	need := int64(26+p.depth*8) + probe.w.Offset
	if need > 0xffffffff || need > int64(len(t.Bytes))-t.Used {
		r.Report.RetainLost++
		return true
	}
	b := t.Bytes[t.Used : t.Used+need]
	clear(b[:26])
	binary.LittleEndian.PutUint32(b, uint32(need))
	binary.LittleEndian.PutUint32(b[4:], p.node)
	binary.LittleEndian.PutUint32(b[8:], uint32(p.depth))
	binary.LittleEndian.PutUint32(b[12:], uint32(probe.w.Offset))
	binary.LittleEndian.PutUint64(b[16:], id)
	b[24] = kind
	for i := 0; i < p.depth; i++ {
		binary.LittleEndian.PutUint32(b[26+8*i:], p.steps[i].ordinal)
		binary.LittleEndian.PutUint32(b[30+8*i:], p.steps[i].index)
	}
	write := tableRetainIn{r: probe.r, w: TableWriter{Buffer: b[26+p.depth*8:]}, limit: limit}
	write.r.Offset = 0
	if !write.payload(kind, 0) || write.w.Overflow {
		r.Report.RetainLost++
		return true
	}
	t.Used += need
	t.Count++
	r.Report.Retained++
	return true
}

type tableRetainIn struct {
	r     TableReader
	w     TableWriter
	limit int64
}

func (s *tableRetainIn) room(n int64) bool { return n >= 0 && n <= s.limit-s.w.Offset }
func tableRetainFileMinimum(kind uint8) int64 {
	if n := tableKindBytes(kind); n != 0 {
		return n
	}
	switch kind {
	case 13:
		return 16
	case 14, 16:
		return 10
	case 15, 30:
		return 8
	case 12, 31, 32, 33:
		return 1
	}
	return 0
}
func (s *tableRetainIn) ref(zero bool) (uint64, bool) {
	if !s.room(8) {
		return 0, false
	}
	v, ok := s.r.Leb()
	if !ok {
		return 0, false
	}
	if v == 0 {
		if !zero {
			return 0, false
		}
		s.w.Put64(0)
		return 0, true
	}
	id, ok := s.r.Resolve(v)
	if !ok || id == 0 || id >= 0xfffffffffffffffd {
		return 0, false
	}
	s.w.Put64(id)
	return id, true
}
func (s *tableRetainIn) raw(n int64) bool {
	if !s.room(n) || !s.r.Has(n) {
		return false
	}
	s.w.Raw(s.r.Buffer[s.r.Offset : s.r.Offset+n])
	s.r.Offset += n
	return !s.w.Overflow
}
func (s *tableRetainIn) framed(kind uint8, n int64, depth int) bool {
	if !s.room(8) {
		return false
	}
	at := s.w.Offset
	s.w.Put64(0)
	start := s.w.Offset
	if !s.content(kind, n, depth) || s.w.Offset-start > 0xffffffff {
		return false
	}
	if !s.w.Measuring {
		binary.LittleEndian.PutUint32(s.w.Buffer[at:], uint32(s.w.Offset-start))
	}
	return true
}
func (s *tableRetainIn) content(kind uint8, n int64, depth int) bool {
	if depth > tableRetainWalkDepthMax || !s.r.Has(n) {
		return false
	}
	end := s.r.Offset + n
	switch kind {
	case 13:
		for {
			ref, ok := s.ref(true)
			if !ok {
				return false
			}
			if ref == 0 {
				break
			}
			if !s.room(1) || !s.r.Has(1) {
				return false
			}
			k := s.r.Get8()
			s.w.Put8(k)
			if !s.payload(k, depth) || s.r.Offset > end {
				return false
			}
		}
	case 14, 16:
		if !s.room(1) || !s.r.Has(1) {
			return false
		}
		k := s.r.Get8()
		s.w.Put8(k)
		count, ok := s.r.Leb()
		if !ok || !s.room(tableLebBytes(count)) {
			return false
		}
		s.w.PutLeb(count)
		minimum := tableRetainFileMinimum(k)
		if kind == 16 {
			minimum = 16
		}
		if minimum <= 0 || count > uint64(max(int64(0), s.limit-s.w.Offset)/minimum) || count > uint64(max(int64(0), end-s.r.Offset)) {
			return false
		}
		for i := uint64(0); i < count; i++ {
			if kind == 16 {
				if _, ok := s.ref(false); !ok {
					return false
				}
				length, ok := s.r.Leb()
				if !ok || length > uint64(end-s.r.Offset) || !s.framed(k, int64(length), depth+1) {
					return false
				}
			} else if !s.payload(k, depth) {
				return false
			}
			if s.r.Offset > end {
				return false
			}
		}
	case 15, 30:
		if !s.payload(kind, depth) {
			return false
		}
	case 17:
		return false
	default:
		if !s.raw(n) {
			return false
		}
	}
	return s.r.Offset == end
}
func (s *tableRetainIn) payload(kind uint8, depth int) bool {
	if width := tableKindBytes(kind); width != 0 {
		return s.raw(width)
	}
	switch kind {
	case 12, 31, 32, 33:
		n, ok := s.r.Leb()
		if !ok || !s.r.Room(n) || !s.room(tableLebBytes(n)) {
			return false
		}
		s.w.PutLeb(n)
		return s.raw(int64(n))
	case 13, 14, 16:
		n, ok := s.r.Leb()
		return ok && s.r.Room(n) && s.framed(kind, int64(n), depth+1)
	case 15:
		id, ok := s.ref(true)
		if !ok {
			return false
		}
		if id == 0 {
			return true
		}
		if !s.room(1) || !s.r.Has(1) {
			return false
		}
		k := s.r.Get8()
		s.w.Put8(k)
		n, ok := s.r.Leb()
		return ok && s.r.Room(n) && s.framed(k, int64(n), depth+1)
	case 30:
		_, ok := s.ref(true)
		return ok
	}
	return false
}

type tableRetainFrame struct {
	numbering       TableNumbering
	ids             TableRetainIds
	writer, measure TableRetainWriter
}
type TableRetainIds struct {
	known          TableIds
	slots          [tableIdCapacity]int
	Numbering      *TableNumbering
	Retain         *TableRetain
	Path           tableRetainPath
	Count          int
	Overflow, Lost bool
}

func (i *TableRetainIds) Ref(id uint64) uint64 {
	before := i.known.Count
	ref := i.known.Ref(id)
	if i.known.Overflow {
		i.Overflow = true
		return 0
	}
	if i.known.Count != before {
		i.Count++
		i.slots[ref-1] = i.Count
	}
	return uint64(i.slots[ref-1])
}
func (i *TableRetainIds) RefAt(ordinal int, id uint64) uint64 {
	before := i.known.Count
	ref := i.known.RefAt(ordinal, id)
	if i.known.Overflow {
		i.Overflow = true
		return 0
	}
	if i.known.Count != before {
		i.Count++
		i.slots[ref-1] = i.Count
	}
	return uint64(i.slots[ref-1])
}
func (i *TableRetainIds) refAtHit(ordinal int, id uint64) uint64 {
	before := i.known.Count
	ref := i.known.refAtHit(ordinal, id)
	if i.known.Overflow {
		i.Overflow = true
		return 0
	}
	if i.known.Count != before {
		i.Count++
		i.slots[ref-1] = i.Count
	}
	return uint64(i.slots[ref-1])
}
func (i *TableRetainIds) recordRef(id uint64) uint64 {
	lo, hi := 0, len(tableRetainKnown)
	for lo < hi {
		m := lo + (hi-lo)/2
		if tableRetainKnown[m] < id {
			lo = m + 1
		} else {
			hi = m
		}
	}
	if lo < len(tableRetainKnown) && tableRetainKnown[lo] == id {
		return i.Ref(id)
	}
	t := i.Retain
	if t == nil {
		i.Lost = true
		return 0
	}
	for k := 0; k < t.idUsed; k++ {
		if t.Ids[k].Id == id {
			return uint64(t.Ids[k].Slot)
		}
	}
	if t.idUsed == len(t.Ids) {
		i.Lost = true
		return 0
	}
	i.Count++
	t.Ids[t.idUsed] = TableRetainId{id, i.Count}
	t.idUsed++
	return uint64(i.Count)
}
func (i *TableRetainIds) Truncate(mark int) {
	for i.known.Count > 0 && i.slots[i.known.Count-1] > mark {
		i.known.Truncate(i.known.Count - 1)
	}
	if t := i.Retain; t != nil {
		for t.idUsed > 0 && t.Ids[t.idUsed-1].Slot > mark {
			t.idUsed--
		}
	}
	i.Count = mark
}
func (i *TableRetainIds) trailer(w *TableRetainWriter) {
	a, b, count := 0, 0, 0
	if i.Retain != nil {
		count = i.Retain.idUsed
	}
	for a < i.known.Count || b < count {
		if b == count || a < i.known.Count && i.slots[a] < i.Retain.Ids[b].Slot {
			w.Put64(i.known.Values[a])
			a++
		} else {
			w.Put64(i.Retain.Ids[b].Id)
			b++
		}
	}
	w.Put64(uint64(i.Count))
}

type tableRetainOut struct {
	r    TableReader
	w    *TableRetainWriter
	ids  *TableRetainIds
	size int64
}

func (s *tableRetainOut) raw(n int64) bool {
	if !s.r.Has(n) {
		return false
	}
	if s.w != nil {
		s.w.Raw(s.r.Buffer[s.r.Offset : s.r.Offset+n])
	}
	s.r.Offset += n
	s.size += n
	return true
}
func (s *tableRetainOut) leb(v uint64) {
	if s.w != nil {
		s.w.PutLeb(v)
	}
	s.size += tableLebBytes(v)
}
func (s *tableRetainOut) ref() (uint64, bool) {
	if !s.r.Has(8) {
		return 0, false
	}
	id := s.r.Get64()
	if id == 0 {
		s.leb(0)
		return 0, true
	}
	ref := s.ids.recordRef(id)
	if s.ids.Lost || s.ids.Overflow {
		return id, false
	}
	s.leb(ref)
	return id, true
}
func (s *tableRetainOut) framed(kind uint8, depth int) bool {
	if !s.r.Has(8) {
		return false
	}
	at := s.r.Offset
	n := s.r.Get32()
	wire := s.r.Get32()
	if s.w == nil {
		before := s.size
		if !s.content(kind, int64(n), depth) || s.size-before > 0xffffffff {
			return false
		}
		wire = uint32(s.size - before)
		binary.LittleEndian.PutUint32(s.r.Buffer[at+4:], wire)
		s.size += tableLebBytes(uint64(wire))
		return true
	}
	s.leb(uint64(wire))
	before := s.size
	return s.content(kind, int64(n), depth) && s.size-before == int64(wire)
}
func (s *tableRetainOut) content(kind uint8, n int64, depth int) bool {
	if depth > tableRetainWalkDepthMax || !s.r.Has(n) {
		return false
	}
	end := s.r.Offset + n
	switch kind {
	case 13:
		for {
			id, ok := s.ref()
			if !ok {
				return false
			}
			if id == 0 {
				break
			}
			if !s.r.Has(1) {
				return false
			}
			k := s.r.Buffer[s.r.Offset]
			if !s.raw(1) || !s.payload(k, depth) || s.r.Offset > end {
				return false
			}
		}
	case 14, 16:
		if !s.r.Has(1) {
			return false
		}
		k := s.r.Buffer[s.r.Offset]
		if !s.raw(1) {
			return false
		}
		count, ok := s.r.Leb()
		if !ok {
			return false
		}
		s.leb(count)
		for i := uint64(0); i < count; i++ {
			if kind == 16 {
				if _, ok := s.ref(); !ok || !s.framed(k, depth+1) {
					return false
				}
			} else if !s.payload(k, depth) {
				return false
			}
			if s.r.Offset > end {
				return false
			}
		}
	case 15, 30:
		if !s.payload(kind, depth) {
			return false
		}
	default:
		if !s.raw(n) {
			return false
		}
	}
	return s.r.Offset == end
}
func (s *tableRetainOut) payload(kind uint8, depth int) bool {
	if n := tableKindBytes(kind); n != 0 {
		return s.raw(n)
	}
	switch kind {
	case 12, 31, 32, 33:
		n, ok := s.r.Leb()
		if !ok || !s.r.Room(n) {
			return false
		}
		s.leb(n)
		return s.raw(int64(n))
	case 13, 14, 16:
		return s.framed(kind, depth+1)
	case 15:
		id, ok := s.ref()
		if !ok {
			return false
		}
		if id == 0 {
			return true
		}
		if !s.r.Has(1) {
			return false
		}
		k := s.r.Buffer[s.r.Offset]
		return s.raw(1) && s.framed(k, depth+1)
	case 30:
		_, ok := s.ref()
		return ok
	}
	return false
}
func tableRetainTail(w *TableRetainWriter) bool {
	ids := w.Ids
	t := ids.Retain
	if t == nil {
		return true
	}
	for at := 0; at < int(t.Used); {
		n := tableRetainRecordSize(t.Bytes[at:])
		b := t.Bytes[at : at+n]
		at += n
		if !t.matches(b, ids.Path, false, false, 0) {
			continue
		}
		mark := ids.Count
		ids.Lost = false
		ref := ids.recordRef(binary.LittleEndian.Uint64(b[16:]))
		depth := int(binary.LittleEndian.Uint32(b[8:]))
		payload := b[26+8*depth:]
		probe := tableRetainOut{r: TableReader{Buffer: payload}, ids: ids}
		if ids.Lost || !probe.payload(b[24], 0) || probe.r.Offset != int64(len(payload)) {
			ids.Truncate(mark)
			ids.Lost = false
			continue
		}
		if w.Measuring {
			w.Advance(tableLebBytes(ref) + 1 + probe.size)
			continue
		}
		ids.Truncate(mark)
		w.PutLeb(ids.recordRef(binary.LittleEndian.Uint64(b[16:])))
		w.Put8(b[24])
		out := tableRetainOut{r: TableReader{Buffer: payload}, ids: ids, w: w}
		if !out.payload(b[24], 0) || out.size != probe.size {
			return false
		}
		b[25] = 1
	}
	return !w.Overflow && !ids.Overflow
}

type tableMessagePlainReader = TableMessageReader
type TableRetainMessageReader struct {
	tableMessagePlainReader
	Retain *TableRetain
	Path   tableRetainPath
}

// Capture starts only after the ordinary skip succeeds. Capacity bounds the
// resolved output before an announced count can expand a zero-bit element.
func (r *TableRetainMessageReader) capture(e TableMessageEntry) bool {
	start := r.Bits.Offset
	if !tableMessageSkip(&r.Bits, r.Vocabulary, r.IndexBits, e, 0) {
		return false
	}
	if r.Retain == nil {
		return true
	}
	t, p := r.Retain, r.Path
	header := int64(26 + p.depth*8)
	limit := int64(len(t.Bytes)) - t.Used - header
	if p.depth > len(p.steps) || limit < 0 {
		r.Report.RetainLost++
		return true
	}
	probe := tableRetainMessageIn{bits: r.Bits, v: r.Vocabulary, w: TableWriter{Measuring: true}, limit: limit}
	probe.bits.Offset = start
	if !probe.payload(e, 0) || probe.bits.Offset != r.Bits.Offset || probe.w.Offset > limit {
		r.Report.RetainLost++
		return true
	}
	need := header + probe.w.Offset
	if need > 0xffffffff {
		r.Report.RetainLost++
		return true
	}
	b := t.Bytes[t.Used : t.Used+need]
	clear(b[:26])
	binary.LittleEndian.PutUint32(b, uint32(need))
	binary.LittleEndian.PutUint32(b[4:], p.node)
	binary.LittleEndian.PutUint32(b[8:], uint32(p.depth))
	binary.LittleEndian.PutUint32(b[12:], uint32(probe.w.Offset))
	binary.LittleEndian.PutUint64(b[16:], e.Id)
	b[24] = e.Shape.Kind
	for i := 0; i < p.depth; i++ {
		binary.LittleEndian.PutUint32(b[26+i*8:], p.steps[i].ordinal)
		binary.LittleEndian.PutUint32(b[30+i*8:], p.steps[i].index)
	}
	write := tableRetainMessageIn{bits: r.Bits, v: r.Vocabulary, w: TableWriter{Buffer: b[header:]}, limit: limit}
	write.bits.Offset = start
	if !write.payload(e, 0) || write.w.Overflow {
		r.Report.RetainLost++
		return true
	}
	t.Used += need
	t.Count++
	r.Report.Retained++
	return true
}

type tableRetainMessageIn struct {
	bits  TableBitReader
	v     *TableVocabulary
	w     TableWriter
	limit int64
}

func (s *tableRetainMessageIn) room(n int64) bool { return n >= 0 && n <= s.limit-s.w.Offset }
func (s *tableRetainMessageIn) ref(zero bool) (TableMessageEntry, bool) {
	ref, ok := s.bits.Get(s.v.RefBits)
	if !ok {
		return TableMessageEntry{}, false
	}
	if ref == 0 {
		if !zero || !s.room(8) {
			return TableMessageEntry{}, false
		}
		s.w.Put64(0)
		return TableMessageEntry{}, true
	}
	e, ok := s.v.Entry(ref)
	if !ok || e.Id == 0 || e.Id >= 0xfffffffffffffffd || !s.room(8) {
		return e, false
	}
	s.w.Put64(e.Id)
	return e, true
}
func (s *tableRetainMessageIn) scalar(e TableMessageEntry) bool {
	width := tableKindBytes(e.Shape.Kind)
	if width == 0 || !s.room(width) {
		return false
	}
	shape := e.Shape
	if shape.Packing == 2 {
		probe := s.bits
		index, ok := probe.Get(shape.Bits)
		if !ok || index > uint64(shape.QCount) {
			return false
		}
	}
	var raw [16]byte
	if !tableMessageReadScalar(&s.bits, shape, &raw) {
		return false
	}
	if shape.Packing == 0 && (shape.Kind >= 2 && shape.Kind <= 5 || shape.Kind >= 20 && shape.Kind <= 24) && shape.Bits > 0 && shape.Bits < 64 {
		v := binary.LittleEndian.Uint64(raw[:])
		if v&(uint64(1)<<uint(shape.Bits-1)) != 0 {
			v |= ^uint64(0) << uint(shape.Bits)
			binary.LittleEndian.PutUint64(raw[:], v)
		}
	}
	s.w.Raw(raw[:width])
	return !s.w.Overflow
}
func (s *tableRetainMessageIn) opaque(e TableMessageEntry, framed bool) bool {
	var n uint64
	var ok bool
	if e.Shape.Kind == 12 || e.Shape.Kind == 33 {
		n, ok = tableMessageCount(&s.bits, e.Shape)
		if !ok {
			return false
		}
		if e.Shape.Kind == 33 {
			n *= 2
		} else if !s.bits.Align() {
			return false
		}
	} else {
		if !s.bits.Align() {
			return false
		}
		n, ok = s.bits.Get(32)
		if !ok {
			return false
		}
	}
	extra := int64(0)
	if framed {
		extra = tableLebBytes(n)
	}
	if n > 0x7fffffff || !s.room(int64(n)+extra) || int64(n)*8 > int64(len(s.bits.Buffer))*8-s.bits.Offset {
		return false
	}
	if framed {
		s.w.PutLeb(n)
	}
	for i := uint64(0); i < n; i++ {
		v, ok := s.bits.Get(8)
		if !ok {
			return false
		}
		s.w.Put8(byte(v))
	}
	return true
}
func (s *tableRetainMessageIn) framed(e TableMessageEntry, depth int) bool {
	if depth > tableRetainWalkDepthMax || !s.room(8) {
		return false
	}
	at := s.w.Offset
	s.w.Put64(0)
	before := s.w.Offset
	if !s.content(e, depth) || s.w.Offset-before > 0xffffffff {
		return false
	}
	if !s.w.Measuring {
		binary.LittleEndian.PutUint32(s.w.Buffer[at:], uint32(s.w.Offset-before))
	}
	return true
}
func (s *tableRetainMessageIn) content(e TableMessageEntry, depth int) bool {
	if depth > tableRetainWalkDepthMax {
		return false
	}
	switch e.Shape.Kind {
	case 17:
		return false
	case 13:
		for {
			entry, ok := s.ref(true)
			if !ok {
				return false
			}
			if entry.Id == 0 {
				return true
			}
			if !s.room(1) {
				return false
			}
			s.w.Put8(entry.Shape.Kind)
			if !s.payload(entry, depth) {
				return false
			}
		}
	case 14, 16:
		return s.elements(e, depth)
	case 15, 30:
		return s.payload(e, depth)
	case 32:
		return true
	case 12, 31, 33:
		return s.opaque(e, false)
	}
	return s.scalar(e)
}
func tableRetainMessageMinimum(kind uint8) int64 {
	if n := tableKindBytes(kind); n != 0 {
		return n
	}
	switch kind {
	case 13:
		return 16
	case 14, 16:
		return 10
	case 15, 30:
		return 8
	case 17:
		return -1
	case 12, 31, 32, 33:
		return 1
	}
	return -1
}
func (s *tableRetainMessageIn) elements(e TableMessageEntry, depth int) bool {
	if e.Element.Kind == 17 {
		return false
	}
	n, ok := tableMessageCount(&s.bits, e.Shape)
	if !ok {
		return false
	}
	if e.Shape.Kind == 14 && e.Element.Kind == 6 && !s.bits.Align() {
		return false
	}
	if !s.room(1 + tableLebBytes(n)) {
		return false
	}
	s.w.Put8(e.Element.Kind)
	s.w.PutLeb(n)
	floor := tableRetainMessageMinimum(e.Element.Kind)
	if e.Shape.Kind == 16 {
		floor = 16
	}
	if floor < 0 || n > uint64((s.limit-s.w.Offset)/floor) {
		return false
	}
	element := TableMessageEntry{Shape: e.Element}
	for i := uint64(0); i < n; i++ {
		if e.Shape.Kind == 16 {
			if _, ok := s.ref(false); !ok || !s.framed(element, depth+1) {
				return false
			}
		} else if !s.payload(element, depth) {
			return false
		}
	}
	return true
}
func (s *tableRetainMessageIn) payload(e TableMessageEntry, depth int) bool {
	switch e.Shape.Kind {
	case 0, 17:
		return false
	case 32:
		if !s.room(1) {
			return false
		}
		s.w.PutLeb(0)
		return true
	case 30:
		_, ok := s.ref(true)
		return ok
	case 15:
		arm, ok := s.ref(true)
		if !ok {
			return false
		}
		if arm.Id == 0 {
			return true
		}
		if arm.Shape.Kind == 0 || !s.room(1) {
			return false
		}
		s.w.Put8(arm.Shape.Kind)
		return s.framed(arm, depth+1)
	case 13, 14, 16:
		return s.framed(e, depth+1)
	case 12, 31, 33:
		return s.opaque(e, true)
	}
	return s.scalar(e)
}
func tableMessageLoadIntoRetain(r TableRetainMessageReader, t *TableTypeInfo, p unsafe.Pointer, size int64) (TableRetainMessageReader, bool) {
	return t.LoadMessageBodyRetain(r, p)
}
func tableMessageRegionIntoRetain(r *TableRetainMessageReader, root *TableTypeInfo, blobs int, region []byte, used *int64) (out unsafe.Pointer, ok bool) {
	r.Retain.reset(nil, nil)
	count, ok := tableMessageNodeOpen(&r.tableMessagePlainReader)
	if !ok {
		r.Report.Malformed = true
		return nil, false
	}
	directoryBytes := (count + 1) * 16
	limit := int64(len(region))
	if *used > limit || directoryBytes > limit-*used {
		r.Report.Malformed = true
		return nil, false
	}
	base := unsafe.Pointer(&region[0])
	directory := unsafe.Slice((*TableNodeDirEntry)(unsafe.Add(base, *used)), int(count+1))
	*used += directoryBytes
	r.IndexBits = tableMessageBits(uint64(count + 1))
	nodes := TableNodeMap{Base: base, Entries: directory}
	recordsStart := r.Bits.Offset
	unknown := int32(0)
	for k := int64(0); k < count; k++ {
		record, good := tableMessageRecordScan(&r.tableMessagePlainReader, root, blobs)
		if !good {
			r.Report.Malformed = true
			return nil, false
		}
		entry := &directory[k+1]
		entry.TypeId = record.id
		if record.size <= 0 {
			entry.Offset = ^uint64(0)
			unknown++
			continue
		}
		if record.size > limit-*used {
			r.Report.Malformed = true
			return nil, false
		}
		entry.Offset = uint64(*used)
		p := unsafe.Add(base, *used)
		if t := root.NodeType(record.id); t != nil {
			t.Reset(p)
		} else {
			*(*TableBlob)(p) = TableBlob{Length: uint32(uint64(record.length))}
		}
		*used += record.size
	}
	fieldsStart := r.Bits.Offset
	walk := *r
	extent := int64(0)
	complete := tableMessageExtent(&walk.tableMessagePlainReader, root, &extent)
	if !complete && tableMessageHasExtent(root) {
		r.Report.Malformed = true
		return nil, false
	}
	rootSize := tableRegionRound(tableRegionRound(int64(root.Size)) + extent)
	if rootSize > limit-*used {
		r.Report.Malformed = true
		return nil, false
	}
	directory[0] = TableNodeDirEntry{Offset: uint64(*used), TypeId: root.Id}
	out = unsafe.Add(base, *used)
	root.Reset(out)
	*used += rootSize
	nodes.Good = true
	r.Retain.reset(base, directory)
	if r.Retain != nil {
		r.Report.RetainLost += unknown
	}
	r.Report.Unknown += unknown
	r.Nodes = nodes
	r.Bits.Offset = recordsStart
	for k := int64(0); k < count; k++ {
		if _, good := r.Bits.Get(r.Vocabulary.RefBits); !good {
			r.Report.Malformed = true
			return out, false
		}
		entry := directory[k+1]
		if entry.TypeId == tableBytesTypeId || entry.TypeId == tableStringTypeId {
			n, good := r.Bits.Get(32)
			if !good || !r.Bits.Align() {
				r.Report.Malformed = true
				return out, false
			}
			start := r.Bits.Offset / 8
			if !r.Bits.Skip(int64(n) * 8) {
				r.Report.Malformed = true
				return out, false
			}
			payload := r.Bits.Buffer[start : start+int64(n)]
			if entry.TypeId == tableStringTypeId && blobs&2 != 0 && !tableUtf8Valid(payload) {
				r.Report.Malformed = true
				return out, false
			}
			if entry.Offset != ^uint64(0) {
				copy(unsafe.Slice((*byte)(unsafe.Add(base, entry.Offset+8)), int(n)), payload)
			}
			continue
		}
		if entry.Offset == ^uint64(0) {
			if !tableMessageSkipBody(&r.Bits, r.Vocabulary, r.IndexBits, 0) {
				r.Report.Malformed = true
				return out, false
			}
			continue
		}
		t := root.NodeType(entry.TypeId)
		walk := *r
		extent := int64(0)
		if !tableMessageExtent(&walk.tableMessagePlainReader, t, &extent) {
			r.Report.Malformed = true
			return out, false
		}
		r.Path = tableRetainPath{at: unsafe.Add(base, entry.Offset), node: uint32(k + 2)}
		*r, ok = tableMessageLoadIntoRetain(*r, t, unsafe.Add(base, entry.Offset), tableRegionRound(int64(t.Size))+extent)
		if !ok {
			return out, false
		}
	}
	if r.Bits.Offset != fieldsStart {
		r.Report.Malformed = true
		return out, false
	}
	r.Path = tableRetainPath{at: out, node: 1}
	*r, ok = tableMessageLoadIntoRetain(*r, root, out, rootSize)
	return out, ok
}

type TableRetainWriter struct {
	Buffer    []byte
	Offset    int64
	Overflow  bool
	Measuring bool
	Ids       *TableRetainIds
}

func (w *TableRetainWriter) Advance(n int64) bool {
	if n < 0 || w.Offset < 0 || n > 0x7fffffffffffffff-w.Offset {
		w.Overflow = true
		return false
	}
	if !w.Measuring && (w.Offset > int64(len(w.Buffer)) || n > int64(len(w.Buffer))-w.Offset) {
		w.Overflow = true
		return false
	}
	w.Offset += n
	return true
}

func (w *TableRetainWriter) Raw(data []byte) {
	at := w.Offset
	if w.Advance(int64(len(data))) && !w.Measuring {
		copy(w.Buffer[at:], data)
	}
}

func (w *TableRetainWriter) Put8(v uint8) {
	at := w.Offset
	if w.Advance(1) && !w.Measuring {
		w.Buffer[at] = v
	}
}

func (w *TableRetainWriter) Put16(v uint16) {
	at := w.Offset
	if w.Advance(2) && !w.Measuring {
		binary.LittleEndian.PutUint16(w.Buffer[at:], v)
	}
}

func (w *TableRetainWriter) Put32(v uint32) {
	at := w.Offset
	if w.Advance(4) && !w.Measuring {
		binary.LittleEndian.PutUint32(w.Buffer[at:], v)
	}
}

func (w *TableRetainWriter) Put64(v uint64) {
	at := w.Offset
	if w.Advance(8) && !w.Measuring {
		binary.LittleEndian.PutUint64(w.Buffer[at:], v)
	}
}

// Put128 writes two little-endian lanes, low first, under one Advance.
func (w *TableRetainWriter) Put128(lo, hi uint64) {
	at := w.Offset
	if w.Advance(16) && !w.Measuring {
		binary.LittleEndian.PutUint64(w.Buffer[at:], lo)
		binary.LittleEndian.PutUint64(w.Buffer[at+8:], hi)
	}
}

// putLebPair writes a one-byte LEB. False means the value needs putLebWide.
// Overflow on a short buffer is handled here so the fast path has no calls.
func (w *TableRetainWriter) putLebPair(v uint64) bool {
	if v >= 128 {
		return false
	}
	at := w.Offset
	end := at + 1
	if at < 0 || end < at {
		w.Overflow = true
		return true
	}
	if w.Measuring {
		w.Offset = end
		return true
	}
	if uint64(end) > uint64(len(w.Buffer)) {
		w.Overflow = true
		return true
	}
	w.Buffer[at] = uint8(v)
	w.Offset = end
	return true
}

func (w *TableRetainWriter) putLebWide(v uint64) {
	// Groups assemble in a ten-byte stack buffer and go to Raw once. Spelling
	// is the old loop's, group for group. One Advance covers the value; raw's
	// capacity test is untouched. A value that does not fit now leaves the
	// buffer alone rather than filling it first; Save answers -1.
	var b [10]byte
	n := 0
	for v >= 128 {
		b[n] = uint8(v) | 128
		v >>= 7
		n++
	}
	b[n] = uint8(v)
	n++
	w.Raw(b[:n])
}

func (w *TableRetainWriter) PutLeb(v uint64) {
	if !w.putLebPair(v) {
		w.putLebWide(v)
	}
}

func (w *TableRetainWriter) Id(id uint64)                { w.PutLeb(w.Ids.Ref(id)) }
func (w *TableRetainWriter) IdAt(ordinal int, id uint64) { w.PutLeb(w.Ids.RefAt(ordinal, id)) }

// headerPair writes a field header whose reference is one LEB byte. False
// means the reference needs headerRest. Overflow on a short buffer is handled
// here so the fast path has no calls, matching the packet runtime's tryWriteBits.
func (w *TableRetainWriter) headerPair(ref uint64, kind uint8) bool {
	if ref >= 128 {
		return false
	}
	at := w.Offset
	end := at + 2
	if at < 0 || end < at {
		w.Overflow = true
		return true
	}
	if w.Measuring {
		w.Offset = end
		return true
	}
	if uint64(end) > uint64(len(w.Buffer)) {
		w.Overflow = true
		return true
	}
	binary.LittleEndian.PutUint16(w.Buffer[at:], uint16(ref)|uint16(kind)<<8)
	w.Offset = end
	return true
}

func (w *TableRetainWriter) headerRest(ref uint64, kind uint8) {
	w.PutLeb(ref)
	w.Put8(kind)
}

// Header writes a field's reference and kind. A reference below 128 is one
// LEB byte, so the pair is one two-byte store. Larger references still go
// through PutLeb then Put8. Bytes match that two-call spelling; a pair that
// does not fit now leaves the buffer alone, and Save answers -1.
func (w *TableRetainWriter) Header(ref uint64, kind uint8) {
	if !w.headerPair(ref, kind) {
		w.headerRest(ref, kind)
	}
}

func (w *TableRetainWriter) Trailer() { w.Ids.trailer(w) }
func tableRegionLoadRetain(region, wire []byte, root *TableTypeInfo, nodeType func(uint64) *TableTypeInfo, blobs int, report *TableReport, retain *TableRetain) unsafe.Pointer {
	retain.reset(nil, nil)
	if report == nil {
		var ignored TableReport
		report = &ignored
	}
	r, verdict := tableOpenFramed(wire, report)
	report.Verdict = verdict
	if verdict != TableOpenOk {
		if verdict == TableOpenDamaged {
			report.Malformed = true
		} else {
			report.Reason = "unsupported wire form"
		}
		return nil
	}
	n, attr, _ := tableRegionMeasure(wire, root, nodeType, blobs)
	if n < 0 || int64(len(region)) < n || len(region) == 0 || uintptr(unsafe.Pointer(&region[0]))%uintptr(tableRegionAlign) != 0 {
		report.Malformed = true
		return nil
	}
	clear(region)
	data := n - attr
	base := unsafe.Pointer(&region[0])
	directory := unsafe.Slice((*TableNodeDirEntry)(unsafe.Add(base, data)), int(attr/16))
	directory[0] = TableNodeDirEntry{0, root.Id}
	nodes := TableNodeMap{Base: base, Entries: directory}
	root.Reset(base)
	retain.reset(base, directory)
	s := tableNodeScanBegin(r)
	used := tableRegionRound(int64(root.Size))
	k := 1
	unknown := int32(0)
	for {
		id, body, ok := s.next()
		if !ok {
			break
		}
		size := tableNodeStorage(id, body, nodeType, blobs)
		directory[k].TypeId = id
		if id == tableStringTypeId && blobs&2 != 0 && !tableUtf8Valid(body.Buffer) {
			directory[k].Offset = ^uint64(0)
			report.Malformed = true
		} else if size <= 0 {
			directory[k].Offset = ^uint64(0)
			unknown++
		} else {
			directory[k].Offset = uint64(used)
			p := unsafe.Add(base, used)
			if t := nodeType(id); t != nil {
				t.Reset(p)
			} else {
				*(*TableBlob)(p) = TableBlob{Length: uint32(uint64(len(body.Buffer)))}
			}
			used += size
		}
		k++
	}
	nodes.Good = s.whole()
	if nodes.Good {
		report.Unknown += unknown
		if retain != nil {
			report.RetainLost += unknown
		}
	} else {
		report.Malformed = true
	}
	if nodes.Good {
		s = tableNodeScanBegin(r)
		k = 1
		for {
			id, body, ok := s.next()
			if !ok {
				break
			}
			if directory[k].Offset != ^uint64(0) {
				p := unsafe.Add(base, directory[k].Offset)
				if t := nodeType(id); t != nil {
					body.Nodes = nodes
					t.LoadBodyRetain(TableRetainReader{tableRetainPlainReader: body, Retain: retain, Path: tableRetainPath{at: p, node: uint32(k + 1)}}, p)
				} else {
					copy(unsafe.Slice((*byte)(unsafe.Add(p, 8)), len(body.Buffer)), body.Buffer)
				}
			}
			k++
		}
	}
	r.Nodes = nodes
	r.Nested = false
	root.LoadBodyRetain(TableRetainReader{tableRetainPlainReader: r, Retain: retain, Path: tableRetainPath{at: base, node: 1}}, base)
	return base
}
func tableRegionSaveRetain(root unsafe.Pointer, info *TableTypeInfo, buffer []byte, measure bool, retain *TableRetain, report *TableReport, allocator ...TableAllocator) int64 {
	if retain != nil {
		retain.idUsed = 0
		retain.clearPlaced()
	}
	frame := tableRetainFrame{}
	var ok bool
	frame.numbering, ok = tableNumber(root, info, nil, allocator...)
	if !ok {
		return -1
	}
	n := &frame.numbering
	defer n.Release()
	ids := &frame.ids
	*ids = TableRetainIds{Numbering: n, Retain: retain, Path: tableRetainPath{at: root, node: 1}}
	w := &frame.writer
	*w = TableRetainWriter{Buffer: buffer, Measuring: measure, Ids: ids}
	w.Put8(1)
	if !info.SaveBodyRetain(w, root) {
		return -1
	}
	w.Offset--
	if len(n.entries) > 1 {
		w.Id(0xffffffffffffffff)
		w.Put8(12)
		payload := tableLebBytes(uint64(len(n.entries) - 1))
		for i := 1; i < len(n.entries); i++ {
			e := &n.entries[i]
			payload += tableLebBytes(ids.Ref(e.id))
			size := tableNodeMeasureRetain(&frame.measure, ids, e)
			if size < 0 {
				return -1
			}
			payload += tableLebBytes(uint64(size)) + size
		}
		w.PutLeb(uint64(payload))
		w.PutLeb(uint64(len(n.entries) - 1))
		for i := 1; i < len(n.entries); i++ {
			e := &n.entries[i]
			w.Id(e.id)
			size := tableNodeMeasureRetain(&frame.measure, ids, e)
			if size < 0 {
				return -1
			}
			w.PutLeb(uint64(size))
			if w.Measuring {
				w.Advance(size)
			} else if !tableNodeWriteRetain(w, e) {
				return -1
			}
		}
	}
	w.Put8(0)
	w.Trailer()
	if w.Overflow || ids.Overflow {
		return -1
	}
	if !measure {
		retain.countLost(report)
	}
	return w.Offset
}
func tableNodeWriteRetain(w *TableRetainWriter, e *tableNodeEntry) bool {
	if e.info != nil {
		path := w.Ids.Path
		w.Ids.Path = tableRetainPath{at: e.node}
		ok := e.info.SaveBodyRetain(w, e.node)
		w.Ids.Path = path
		return ok
	}
	length := (*TableBlob)(e.node).Length
	w.Raw(unsafe.Slice((*byte)(unsafe.Add(e.node, 8)), int(length)))
	return !w.Overflow
}
func tableNodeMeasureRetain(w *TableRetainWriter, ids *TableRetainIds, e *tableNodeEntry) int64 {
	*w = TableRetainWriter{Measuring: true, Ids: ids}
	if !tableNodeWriteRetain(w, e) {
		return -1
	}
	return w.Offset
}
